window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q08"]=window.__LIBQ["the-gioi-hoan-my"]["q08"]||{};window.__LIBQ["the-gioi-hoan-my"]["q08"]["cotTruyen"]=[{"chuong":701,"tieuDe":"Người Cổ Xưa Nhất","tomTat":"Cuộc chiến trên bình nguyên màu máu tạm dừng khi mọi bên chờ kết quả giao tranh giữa Chiến đế và lão Thiên Nhân. Hai cổ tổ đã đánh quyết liệt nhưng không tử chiến, bởi người thắng cũng sẽ kiệt quệ và khiến tộc mình suy yếu, nên Chiến tộc cùng Thiên Nhân tộc lần lượt thu quân. Vân Hi vui mừng vì có thể kết thúc lưu vong và trở về tộc, song nàng nghe lời Thạch Hạo rời cấm địa trước để không trở thành gánh nặng. Thạch Hạo theo cầu bạch ngọc tiến sâu vào cấm địa, phát hiện chiếc kén đã vỡ cùng tàn tích lột xác và nghi thiếu nữ tuyết y trước mặt vừa niết bàn sống lại. Thiếu nữ giả nhận mình từng là sư phụ Lôi đế, trêu rằng Thạch Hạo là Lôi đế chuyển thế, nhưng hắn nhanh chóng nhìn ra sơ hở. Nàng còn cho biết Ma huyết quỷ thần thụ đã về với tổ tiên và tự nhận vừa rời cố hương sâu trong Cấm khu không người, khiến Thạch Hạo tiếp tục hoài nghi lai lịch thật của nàng."},{"chuong":702,"tieuDe":"Diệp Khuynh Tiên","tomTat":"Thạch Hạo dò hỏi thiếu nữ mặc tuyết y trong cấm địa nhưng không thể nhìn thấu cảnh giới của nàng, rồi được nàng cho xem Kỳ Lân trùng có thể cắn nát và ăn binh khí cấp Tôn giả. Thiếu nữ dùng võ đạo Thiên nhãn nhận ra Vân Hi mang Thiên Mệnh thạch, thoáng muốn chiếm đoạt nhưng tạm bỏ qua vì còn muốn gặp lão Thiên Nhân. Nàng tuyên bố thu Thạch Hạo làm người hầu, nói mình từng đi qua Tiên điện và tiết lộ tên là Diệp Khuynh Tiên. Thạch Hạo trở lại gặp Vân Hi, từ chối lời mời tới Thiên Nhân tộc dù biết Chiến tộc có thể trả thù, sau đó hộ tống nàng tới chỗ tộc nhân rồi chia tay. Hắn dùng pháp môn Côn Bằng và Súc địa thành thốn rời chiến trường, ẩn sâu dưới lòng đất để tránh các cao thủ Thiên Thần. Hai ngày sau, một Thiên Thần áo tím của Thiên Nhân tộc lần theo dấu vết Thiên Nhân đan, dùng Thiên Thần pháp liên khóa và kéo hắn lên mặt đất. Vị Thiên Thần sau đó buông pháp liên, khẳng định không có ác ý và mời Thạch Hạo về Thiên Nhân tộc để cảm tạ việc cứu Vân Hi."},{"chuong":703,"tieuDe":"Thiên Chi Thành","tomTat":"Thạch Hạo nhiều lần từ chối lời mời tới Thiên Nhân tộc nhưng cuối cùng phải đi cùng Thiên Thần Thích Thác vì không đủ sức thoát thân. Tại một thành trì ở Thiên châu, hắn gặp lại Vân Hi và biết hai người trẻ tuổi dung hợp Thiên Mệnh thạch mất tích đã gặp nạn, trong đó một người chết còn người kia chỉ còn một tia sinh cơ. Đoàn người lập tức dùng truyền tống trận và cốt thuyền trở về lãnh địa Thiên Nhân tộc, rồi đưa người bị thương vào thần trì thái cổ cứu chữa. Trên đường đi, Thạch Hạo chứng kiến bãi chăn thả và dược viên rộng mười vạn dặm cùng đại trận từng chống đỡ công kích của Chiến đế. Sau nhiều lớp kiểm tra, hắn tiến vào Thiên Chi Thành, cổ thành trên trời và là tổ địa tối cao của những Thiên Nhân có huyết thống cao quý. Khi được tiếp đãi tại nơi nghỉ, hắn bị Tê Hà dò hỏi chuyện đạo lữ, cho thấy Thiên Nhân tộc đặc biệt quan tâm tới việc kết duyên của hắn."},{"chuong":704,"tieuDe":"Ở Rể?","tomTat":"Sau khi được gợi ý về chuyện đạo lữ, Thạch Hạo vừa trêu hai thiếu nữ hầu cận vừa âm thầm tìm đường rời Thiên Chi Thành vì lo thân phận bị bại lộ. Hắn nhận ra đại thành rộng như một tiểu thiên thế giới và được đại trận đủ sức ngăn cản cả Thiên Thần bảo vệ, nên không thể cưỡng ép thoát đi. Hai thiếu nữ dẫn hắn tới sân diễn võ, nơi Phi Tiên thạch khẽ rung và khiến hắn suýt tiến vào trạng thái ngộ đạo, nhưng hắn kịp áp chế dị tượng để che giấu căn cơ. Hai ngày sau, Thạch Hạo xin cáo từ nhưng Tê Hà đích thân giữ hắn lại bằng lời hứa tặng cả một lò Thần Hỏa đan phục vụ việc đột phá Thần Hỏa cảnh. Tê Hà tiếp tục thăm dò khả năng để hắn kết đạo lữ với một trong ba minh châu và gia nhập Thiên Nhân tộc, còn Thạch Hạo cố ý đáp lời phóng túng khiến bà nghi ngờ phẩm hạnh của hắn. Nghe tin, hai tuyệt đại giai nhân của Thiên Nhân tộc tới chất vấn và tuyên bố hắn chỉ có tư cách bàn chuyện đạo lữ nếu nhấc được Phi Tiên thạch."},{"chuong":705,"tieuDe":"Hai Mỹ Nhân Tuyệt Sắc","tomTat":"Mạn Châu Sa Hoa và Hoa Sen tới tịnh xá ven hồ theo lời triệu tập của Tê Hà sau khi biết có người nhắm tới họ trong chuyện đạo lữ. Thạch Hạo cố tình nhìn ngắm không kiêng dè rồi tuyên bố muốn lấy cả hai, khiến hai minh châu và Tê Hà đều nổi giận. Mạn Châu Sa Hoa đưa ra thử thách buộc hắn nhấc Phi Tiên thạch, một kỳ thạch mang quy tắc quái lạ từng khiến kỳ tài gãy tay và tổn thương đạo cơ. Sau khi mặc cả, hai bên thống nhất rằng Thạch Hạo phải rời đi nếu thất bại, còn nếu thành công thì chuyện kết đạo lữ sẽ theo lời hắn. Hai thiếu nữ hẹn hắn tới sân diễn võ sau một canh giờ rồi rời khỏi tịnh xá. Khi chỉ còn lại mình, Thạch Hạo khôi phục vẻ bình tĩnh và tiết lộ rằng thái độ háo sắc chỉ là kế chọc giận hai minh châu, nhằm khiến thế lực phía sau họ đẩy hắn ra khỏi Thiên Chi Thành. Tuy nhiên, hắn biết ý chí của Thiên Thần không dễ lay chuyển và còn lo sức mạnh của mình có thể khiến kế hoạch cố ý thất bại phát sinh biến số."},{"chuong":706,"tieuDe":"Phi Tiên Thạch","tomTat":"Tin Mạn Châu Sa Hoa và Hoa Sen có thể kết thành đạo lữ với Ma Hi lan khắp Thiên Chi Thành, khiến thế hệ trẻ Thiên Nhân tộc bất bình và tụ tập gây náo động. Thạch Hạo nhận ra hai thiếu nữ cố ý thúc đẩy dư luận để phản đối sự sắp xếp của tộc và buộc hắn rời thành. Bị chặn ngoài sân diễn võ, hắn giả làm người ngoài cuộc, tự ca ngợi Ma Hi rồi bất ngờ công khai thân phận trước đám đông. Tại sân diễn võ, các kỳ tài lần lượt thử nâng Phi Tiên Thạch nhưng chỉ có thể lay động hoặc nhấc nó lên nửa thước trong tình trạng bị ép chảy máu. Thạch Hạo chấp nhận sẽ rời Thiên Chi Thành nếu thất bại, song ngay khi hắn chạm vào, hòn đá đã tự dính vào tay và nổi lên ba thước dù hắn chưa dùng lực. Quy tắc trong đá khiến huyết nhục hắn cộng hưởng, đánh thức những phù văn và bí lực giống bảo thuật Thạch Nghị từng thi triển. Thạch Hạo nhận ra dấu vết bảo thuật vô địch thuộc khối Chí Tôn cốt đầu tiên đã bị lấy khỏi cơ thể mình đang tái hiện sâu trong huyết nhục."},{"chuong":707,"tieuDe":"Thượng Thương Chi Thủ","tomTat":"Khi nhấc Phi Tiên thạch, Thạch Hạo phát hiện dấu vết cốt văn của khối Chí Tôn cốt từng bị lấy khỏi cơ thể đang tái hiện trong máu thịt. Đạo âm từ kỳ thạch đưa hắn vào trạng thái không minh, giúp hắn quan sát và ghi nhớ những biến hóa của bảo thuật trời sinh. Trong lúc Mạn Châu Sa Hoa, Hoa Sen và đám đông cho rằng hắn sắp thất bại, cơ thể hắn vẫn vô thức nâng kỳ thạch ngày càng cao. Kiếp quang Thượng Thương sau đó ngưng tụ thành bàn tay trắng như ngọc phủ kín ký hiệu, khiến hắn lĩnh ngộ hình thái hoàn chỉnh mang tên Thượng Thương chi thủ. Dùng Trùng đồng quan sát kỳ thạch, hắn còn phát hiện một dị vật bị sương mù che phủ và nghi đó là cổ kinh, nhưng không thể nhìn rõ. Cuối cùng, Thạch Hạo nâng Phi Tiên thạch qua vai rồi giơ cao quá đầu, vượt qua thành tích của những thiên tài Thiên Nhân tộc trước đó."},{"chuong":708,"tieuDe":"Tiên Linh Lung","tomTat":"Tại sân diễn võ, Phi Tiên thạch giao cảm với thần văn trong cơ thể Thạch Hạo rồi tự lơ lửng qua đầu hắn, tạo nên kỳ tích chưa người Thiên Nhân nào từng đạt được. Thạch Hạo nhờ đó ngộ Thượng Thương chi thủ suốt một canh giờ, nhưng pháp môn quá phức tạp nên hắn chưa thể hiểu và ghi nhớ trọn vẹn. Tê Hà nhận ra trạng thái ngộ đạo, giải tán đám đông và đích thân hộ pháp, trong khi Mạn Châu Sa Hoa cùng Hoa Sen lo sợ phải thực hiện vụ cá cược trở thành đạo lữ của hắn. Hai thiếu nữ lấy chuyến săn bắn và hái dược làm cớ đưa Thạch Hạo tới vực sâu có đầu mối không gian, nhưng hắn lại chủ động lao xuống để tìm đường thoát khỏi Thiên Chi Thành. Thích Thác dùng pháp liên kéo hắn trở lại, đưa cả đoàn về thành rồi quyết định tác thành hôn sự và âm thầm chọn Thạch Hạo làm Người hộ đạo tương lai của thế hệ trẻ Thiên Nhân tộc. Thạch Hạo được đặc cách mang Phi Tiên thạch về chỗ ở tiếp tục tu hành, còn Mạn Châu Sa Hoa và Hoa Sen bị phái tới chăm sóc hắn. Cuối cùng, Thích Thác tiết lộ bên trong Phi Tiên thạch có Tiên Linh Lung, một tiên khí từ kỷ nguyên Tiên cổ có thể dựa vào vật chất bất tử để khai thông thiên địa và hiển hóa kinh văn đại đạo."},{"chuong":709,"tieuDe":"Lừa Nam Gạt Nữ","tomTat":"Tiên Linh Lung phát động dị tượng trên người Thạch Hạo, khiến Thích Thác nhận định bảo vật đang tu bổ những đạo pháp khuyết thiếu và làm một bảo thuật tuyệt thế dần thành hình. Thích Thác kể rằng sáu đại Thiên Nhân từng mang bảo vật tiến vào Cấm khu tìm vật chất bất tử, nhưng năm người không trở về và người sống sót duy nhất không tiết lộ tai họa đã gặp. Nhận thấy cơ hội thu được tiên kinh vô thượng, ông ra lệnh phải giữ Thạch Hạo ở lại, còn Thiên Nhân tộc tiếp tục bảo vệ và cung cấp tài nguyên cho hắn. Thạch Hạo dùng Phi Tiên thạch lĩnh ngộ các phù văn còn lại trong cơ thể và suy đoán khí tức Tiên đạo từ truyền thừa Lôi Hoàng đã kích thích kỳ thạch, song vẫn âm thầm lo tìm đường thoát khỏi Thiên Chi Thành. Mạn Châu Sa Hoa và Hoa Sen lợi dụng sự bất mãn của thế hệ trẻ để dẫn đám đông tới gây sức ép, nhưng Thạch Hạo phản kích bằng lời đồn hai nàng mang thai rồi kéo cả hai đi trước khi Tê Hà xuất hiện giải tán mọi người. Hắn tiếp tục đặt Phi Tiên thạch bên hồ và tuyên bố chỉ người nhấc được nó mới đủ tư cách khiêu chiến, qua đó chặn toàn bộ những thiên tài đang kéo tới. Cuối chương, Vân Hi hoàn tất dung hợp Thiên Mệnh thạch, khiến các Thiên Thần đồng loạt xuất quan và đưa Thạch Hạo tới gần biến cố mà hắn đã lo ngại."},{"chuong":710,"tieuDe":"Thân Phận Bị Tiết Lộ","tomTat":"Sau khi các Thiên Thần xuất quan, Thạch Hạo tiếp tục được bảo vệ để ngộ đạo bên hồ với sự hỗ trợ của Tiên Linh Lung, bởi cao tầng Thiên Nhân tộc mong hắn lĩnh hội một bí pháp vô thượng. Vân Hi, U Vũ và một kỳ tài trẻ tuổi khác hoàn thành dung hợp Thiên Mệnh thạch, được toàn thành nghênh đón và xác nhận có tiềm năng bước từ giai đoạn Nhân sang giai đoạn Thiên. Trong lúc thế hệ trẻ bàn luận về Ma Hi, Vân Hi thừa nhận hắn vô cùng mạnh, còn tin hắn từng giết một Chiến vương khiến ba kỳ tài kinh ngạc. Thích Thác triệu người điều tra trở về báo cáo rằng một Chiến vương trẻ tuổi quả thật đã chết tại bình nguyên màu máu và kẻ hạ sát được cho là Hoang. Các Thiên Thần từ đó liên hệ Ma Hi với chiến tích tại bí cảnh Nguyên Thiên, truyền thừa Lôi đế và những bảo thuật chí cao, đồng thời lo ngại thiên tư của hắn sẽ trở thành mối uy hiếp. Họ quyết định triệu Thạch Hạo vào cổ điện để trực tiếp xác nhận lai lịch. Trước mặt Vân Hi, U Vũ, kỳ tài thứ ba và các Thiên Thần, Thạch Hạo không tiếp tục che giấu mà thẳng thắn tự nhận mình là Hoang, khiến cả cổ điện rơi vào yên lặng."},{"chuong":711,"tieuDe":"Mưa To Gió Lớn Đã Tới","tomTat":"Thân phận Ma Hi chính là Hoang bị công khai trước cao tầng Thiên Nhân tộc, khiến Vân Hi và U Vũ kinh ngạc, còn các Thiên Thần lập tức chú ý tới tiên kinh Lôi Đế trong tay hắn. Để tự bảo vệ, Thạch Hạo dựng nên lai lịch đến từ vùng sâu Cấm khu ngoài ba ngàn châu và viện tổ huấn để từ chối tiết lộ, nhưng lời khai không qua được thần giác của các Thiên Thần. Cao tầng Thiên Nhân tộc quyết định cho hắn tiếp tục dùng Phi Tiên thạch ngộ pháp nhằm kéo dài thời gian, đồng thời cân nhắc bồi dưỡng hắn thành Người hộ đạo nếu hắn chịu ở lại và giao ra truyền thừa. Họ cũng lo Thạch Hạo sẽ ôm hận rồi trở thành đại họa nên chuẩn bị đề phòng và tính đến việc dùng cốt kinh kiểm tra căn nguyên của hắn. Trở lại hồ nhỏ, Thạch Hạo hiểu mình chưa thể rời Thiên Chi Thành, bèn gạt bỏ tạp niệm và bắt đầu chuyên tâm tìm hiểu Bàn tay Thượng Thương. Bên ngoài lãnh địa, Thiên Thần Chiến tộc xuất hiện khiến trống trời vang lên, sau đó cốt thuyền và chiến thuyền cấp Thiên Thần của các đại giáo khác cũng liên tiếp áp sát. Thích Thác kết luận Chiến tộc đã tung tin về Hoang để liên kết nhiều đại giáo cùng gây sức ép lên Thiên Nhân tộc và tranh đoạt tiên kinh."},{"chuong":712,"tieuDe":"Báo Đáp Như Thế Này","tomTat":"Một Thiên Thần áo đen của Minh thổ tiến vào Thiên Chi Thành, yêu cầu mượn kinh văn Lôi đế và cảnh báo nhiều đại giáo đang cùng gây sức ép lên Thiên Nhân tộc. Các Thiên Thần của Thiên Nhân tộc dùng cốt kính soi ra chân thân Thạch Hạo rồi tìm cách dò xét thức hải, nhưng cấm chế nguyên thần của hắn khiến họ phải dừng lại. Bất Lão sơn, Ma Quỳ viên, Thiên quốc cùng nhiều đạo giáo lần lượt xuất hiện, sau đó một tiên chuông hỗn độn cũng tự tiến vào thành để thay chủ nhân đòi xem kinh văn. Một Thiên Thần dựa vào ký ức từ thức hải của tổ phụ Vân Hi nhận ra Hoang chính là Thạch Hạo, đồng thời tiết lộ chiến tích giết bảy thần cùng các bảo thuật mà hắn nắm giữ. Khi khí tức Tiên đạo trong người Thạch Hạo cạn sạch, Tiên Linh Lung không còn phát động được và Thiên Nhân tộc quyết định bắt giữ hắn mà không kiểm chứng kỹ thương thế. Thích Thác dùng Thiên Thần pháp liên phá Thất Thập Nhị Biến, khiến chân thân Thạch Hạo hiện ra trước Vân Hi và U Vũ. Vân Hi kinh hãi khi nhận ra người từng hộ tống mình, còn U Vũ cùng các Thiên Thần buộc tội hắn che giấu thân phận để thâm nhập Thiên Nhân tộc. Thạch Hạo đáp lại bằng cách nhắc tới hành trình huyết chiến bảo vệ Vân Hi và công khai chất vấn sự báo đáp của Thiên Nhân tộc."},{"chuong":713,"tieuDe":"Tù Nhân","tomTat":"Thạch Hạo lên án Thiên Nhân tộc vong ân vì hắn đã liều chết hộ tống Vân Hi nhưng lại bị bắt giữ và mưu đoạt bảo thuật, còn U Vũ phản bác rằng hắn che giấu chân thân vì có ý đồ. Vân Hi cầu xin Thích Thác thu hồi mệnh lệnh nhưng bị một lão Thiên Thần cưỡng ép đưa khỏi nơi đối chất, sau đó cùng U Vũ trở về nơi bế quan. Khi dụ dỗ Thạch Hạo giao bí thuật thất bại, Thích Thác và các cao tầng Thiên Nhân tộc bàn cách dùng Lục thiên, đại trận thần hồn, đại trận vãng sinh cùng bí bảo để phá cấm chế nguyên thần, dù việc này có thể hủy diệt thân thể hắn. Thạch Hạo bị tống xuống nhà giam trọng phạm, nơi chỉ nhốt cường giả từ Chân Thần trở lên và có cả chuẩn Thiên Thần lẫn Thiên Thần. Hắn truyền âm hứa trao tiên kinh Lôi Đế để kích động các tù nhân phá ngục, khiến cả nhà giam rung chuyển bởi khí tức của nhiều cường giả. Quản ngục tức giận đưa hắn vào thạch thất và dùng thiết kiếm đâm xuyên lồng ngực nhưng vẫn không dám giết hắn vì mệnh lệnh của cao tầng. Cùng lúc đó, thần chủ Khổng Tước dẫn đoàn khách tới Thiên Chi Thành, được các Thiên Thần long trọng nghênh tiếp, trong khi một người quen chưa lộ danh tính của Thạch Hạo đứng bên cạnh và quan sát xung quanh."},{"chuong":714,"tieuDe":"Đại Náo Thiên Nhân Tộc","tomTat":"Khổng Cầu Kỳ theo đoàn cao thủ Khổng Tước tộc đến Thiên Nhân tộc, trong khi thần chủ Khổng Tước được các Thiên Thần tiếp đón trọng thể và hỏi thẳng về Hoang. Vì đối phương muốn gặp truyền nhân Lôi Đế để cảm ứng khí tức Tiên, Thích Thác phải sai người đưa Thạch Hạo từ địa lao tới cung điện. Trước đó, Thạch Hạo đã bị quản ngục dùng hơn mười nhát kiếm xuyên thủng thân thể để ép giao Bảo thuật Lôi Đế, nhưng hắn vẫn cự tuyệt và âm thầm quyết ý sẽ trở lại quét ngang Thiên Chi Thành nếu sống sót. Khổng Cầu Kỳ theo hai Chân Thần xuống ngục, nhận ra Hoang chính là Thạch Hạo từng sống tại Thạch thôn và vô cùng phẫn nộ trước thương thế của cố nhân. Hắn tấn công quản ngục, dùng bí bảo chặt đứt xiềng xích, giúp Thạch Hạo cầm máu và truyền tiếng cầu viện đoàn Khổng Tước tộc. Khi Thạch Hạo được đưa tới cung điện, Khổng Cầu Kỳ công khai xác nhận hắn là huynh đệ ở hạ giới, người của Thạch thôn và đệ tử Liễu Thần. Chương kết thúc khi Khổng Cầu Kỳ chỉ mặt các cường giả Thiên Nhân tộc, chất vấn việc họ tra tấn người từng bảo vệ Vân Hi và mưu đồ đoạt bảo thuật của hắn."},{"chuong":715,"tieuDe":"Thần Chủ Khổng Tước","tomTat":"Thần chủ Khổng Tước kể lại cơ duyên thuở nhỏ khi một giọt chất lỏng từ cây liễu thần bí rơi trúng ông, thay đổi vận mệnh và giúp ông nhanh chóng quật khởi trong tộc. Từ những gì từng chứng kiến, ông tin Liễu Thần chưa chắc đã chết sau khi tiến vào cánh cửa Nguyên thủy và có thể tái hiện trên thế gian. Trong cung điện Thiên Nhân tộc, Khổng Cầu Kỳ công khai mắng các cao tầng vong ân phụ nghĩa, đòi giải thích cho việc giam giữ Thạch Hạo và xin thánh đan chữa thương cho bạn. Thần chủ Khổng Tước xác nhận sư tôn của Thạch Hạo từng có ân với mình, tuyên bố sẽ bảo vệ mạng sống thiếu niên và đánh văng một Chân Thần dám xen lời. Thích Thác cùng các Thiên Thần vẫn kiên quyết không thả Thạch Hạo vì nhắm tới bảo thuật, tiên kinh và lo sợ thiên tư của cậu sẽ trở thành đại họa. Người hộ đạo già nua của Thiên Nhân tộc xuất hiện ngăn cản, nhưng ngay trong lần giao phong đầu tiên đã bị thần quang năm màu đánh thổ huyết, đẩy lùi và làm gãy một chiếc sừng. Thần chủ Khổng Tước cảnh báo việc bức hại đệ tử Liễu Thần có thể khiến Thiên Nhân tộc sa sút, thậm chí bị xóa tên khỏi thượng giới."},{"chuong":716,"tieuDe":"Chư Giáo Cùng Tới","tomTat":"Thần chủ Khổng Tước áp đảo Người hộ đạo Thiên Nhân tộc, chém gãy chiếc sừng thần thông và phá tan quy tắc cùng sao trời do đối phương dẫn xuống. Người hộ đạo mở đại trận Hỗn độn thái cổ, nhưng Lão Thiên Nhân kịp xuất quan hóa giải nguy cơ đại chiến giữa Thiên Nhân tộc và Khổng Tước tộc rồi rời đi khi cảm nhận Chiến đế. Minh chủ, Giáo chủ Bổ Thiên giáo và người đứng đầu nhiều đạo thống lần lượt tới Thiên Chi Thành, khiến Thạch Hạo trở thành tâm điểm tranh đoạt vì thù oán cũ và tiên kinh Lôi đế. Thạch Hạo từ chối lời mời của Giáo chủ Bổ Thiên giáo, chỉ chấp nhận đi cùng Thần chủ Khổng Tước. Chủ cung Hỏa Ma đòi giết Hoang để trả thù cho môn nhân, còn Phó giáo chủ Thiên quốc thay mặt đạo thống tuyên bố Hoang không thể lưu. Giữa lúc tình thế gần như tuyệt lộ, Diệp Khuynh Tiên bước vào đại điện, công khai tuyên bố Thạch Hạo là người của mình và một mình đối diện đông đảo giáo chủ để bảo vệ hắn."},{"chuong":717,"tieuDe":"Diệp Khuynh Tiên Đầy Ngang Ngược","tomTat":"Diệp Khuynh Tiên một mình tiến vào cung điện cổ của Thiên Nhân tộc, công khai đối đầu các Thiên Thần và Giáo chủ đang hiện diện. Chủ cung Hỏa Ma dùng lông hạc đỏ, Hỏa đạo và lôi đình tấn công nàng, nhưng các đòn đánh đều bị gợn sóng thần bí phá giải, còn bản thân hắn bị đánh trọng thương. Chiến lực và tuổi tác của Diệp Khuynh Tiên khiến mọi người chấn động, trong khi Khổng Cầu Kỳ lớn tiếng gọi nàng là Chân Tiên. Nàng sau đó chất vấn Thiên Nhân tộc về việc giam giữ Thạch Hạo, khẳng định mình từng chứng kiến hắn hộ tống Vân Hi qua bình nguyên màu máu. Vân Hi cũng xác nhận đại ân của Thạch Hạo và cầu xin cho hắn, nhưng bị Thích Thác dùng uy áp ngăn lại. Các đại Giáo chủ thử dùng thần niệm dò xét Diệp Khuynh Tiên song bị màn sáng hộ thể thần bí ngăn cách. Cuối cùng, nàng tuyên bố Thạch Hạo là người của mình và yêu cầu Thiên Nhân tộc phải đưa ra lời giải thích cùng vật bàn giao đủ thành ý."},{"chuong":718,"tieuDe":"Thần Hình Tiên Đạo","tomTat":"Diệp Khuynh Tiên đối chất với các Thiên Thần tại Thiên Chi Thành, bác bỏ việc Thiên Nhân tộc giam giữ ân nhân và tuyên bố sẽ đưa Thạch Hạo đi. Thích Thác dùng hồ lô vỏ tím trấn áp nàng nhưng bị những gợn sóng kỳ dị cắt đứt liên hệ với pháp khí, khiến hồ lô bị đoạt và luyện hóa. Diệp Khuynh Tiên tiếp tục dùng Võ đạo Thiên nhãn tái hiện cảnh Thạch Hạo bị tra tấn trong địa lao, sau đó bắt quản ngục và phế sạch tu vi của hắn. Khi các Thiên Thần cùng một Giáo chủ ra tay, nàng gọi ra thần hình Tiên đạo để giam cầm pháp khí và đánh trọng thương nhiều đối thủ. Phó chủ Thiên quốc dùng huyết kiếm thử sức nhưng cũng bị đẩy lui, qua đó xác nhận bóng người này là một trong hai bộ thần hình Tiên đạo được truyền tụng trên thế gian. Diệp Khuynh Tiên thu thần hình vào một pháp khí trông như cổ thuẫn nhưng thực chất là mảnh chuông vỡ. Lão Thiên Nhân chấp thuận để nàng đưa Thạch Hạo đi, song nàng chưa rời thành mà tiếp tục hỏi ông về Minh ước Thái cổ. Việc Lão Thiên Nhân thừa nhận vẫn nhớ minh ước khiến những Giáo chủ cổ xưa nhất hiện diện phải kinh động."},{"chuong":719,"tieuDe":"Rời Đi","tomTat":"Diệp Khuynh Tiên truyền đạt yêu cầu thực hiện minh ước Thái cổ, còn Lão Thiên Nhân quả quyết nhận lời dù đã gần tọa hóa. Nàng tiếp tục buộc Thiên Nhân tộc trả lời về việc bắt giữ Thạch Hạo và xin tìm hiểu Tiên Linh Lung làm khoản bồi thường, sau đó quyết định đưa hắn rời đi ngay. Bất chấp sự phản đối của Minh chủ, Lão Thiên Nhân ra lệnh chuẩn bị truyền tống trận vượt châu hướng tới Tử Vi châu. Trước lúc chia tay, Diệp Khuynh Tiên tiết lộ cổ thuẫn của mình là hồn chuông đang bị một nhân vật sở hữu thân chuông hư hỏng nhắm tới, rồi bí mật trao Phá giới phù cho Thạch Hạo. Khi thông đạo truyền tống mở ra, Chủ Ma Quỳ viên, Phó giáo chủ Thiên quốc, Minh chủ cùng các cường giả Thiên Nhân tộc dùng linh thân truy bắt hắn, trong khi Thần chủ Khổng Tước chặn Minh chủ. Thạch Hạo lập tức kích hoạt Phá giới phù, khiến thông đạo bị vặn vẹo và tọa độ thay đổi liên tục. Hắn thoát khỏi toàn bộ truy binh, rời Thiên Chi Thành nhưng nơi đến thực sự không còn xác định."},{"chuong":720,"tieuDe":"Hỏa Châu","tomTat":"Phá giới phù tiêu hao toàn bộ thần năng để mở đường khỏi hư không, đưa Thạch Hạo đang trọng thương xuống một đại thảo nguyên xa lạ. Nhớ lại việc mình từng bảo vệ Vân Hi nhưng vẫn bị Thiên Nhân tộc giam cầm và làm nhục, hắn quyết tâm quật khởi rồi trở về thanh toán các thế lực từng hãm hại mình. Trên đường tìm nơi có người sinh sống, hắn chứng kiến hàng nghìn kỵ sĩ của Hắc Lang tộc và Huyết sư đoàn giao chiến, trong đó hai Chân Thần của đôi bên đánh đến lưỡng bại câu thương. Qua cuộc tranh cãi giữa hai phe, hắn biết họ đang tranh đoạt manh mối Hỗn độn diễm, một ngọn lửa truyền thuyết có thể dùng để xây dựng đạo cơ khi tiến vào Thần Hỏa cảnh. Thạch Hạo sau đó khống chế tâm thần những kỵ sĩ trọng thương để tra hỏi và xác định mình đã tới Hỏa châu, cách Thiên Châu ít nhất hàng chục đến gần trăm châu. Hắn cũng biết Hỏa châu tiếp giáp Thiên Tiên châu và Côn châu, đồng thời là vùng hỗn loạn giàu thần quáng, thần liệu, truyền thuyết tiên kim và cơ duyên dành cho người mạo hiểm cùng thiên tài các đại tộc."},{"chuong":721,"tieuDe":"Vùng Đất Hiếm Thấy","tomTat":"Thạch Hạo nhận thấy Hỏa châu thường xuất hiện những ngọn lửa kỳ dị có thể thiêu sạch thi thể, nên trong lúc mang thương tích hắn quyết định tìm khu dân cư thay vì tùy tiện bế quan. Trên đường tới Phù Phong thành, hắn bị Lão Mặc lừa vào một cứ điểm buôn nô lệ nhưng đã giết tên cai nô, đánh chết Hắc Ưng, hạ Lão Mặc rồi đoạt roi cấp Thần cùng Lam Linh kim trước khi thiêu hủy nơi này. Vào Phù Phong thành, hắn chứng kiến cảnh chém giết công khai và nhận ra thành trì gần như không có trật tự. Hắn dùng Trùng đồng nhìn thấu đoạn Tuyết Nguyệt giả do người của Kim dược đường chào bán, đồng thời phát hiện một cao thủ Thần Hỏa đang dùng bảo thuật trộm đồ giữa phố. Sau đó, hai tuyệt đại thiên kiêu của thư viện Thần Nhai cưỡi Xích Long câu đáp xuống thành và được Thạch Hạo đánh giá là những sơ đại có chân huyết nguyên thủy mạnh mẽ. Trong đoàn người tới đón họ, Thạch Hạo dùng Trùng đồng nhận ra một cô gái quen đang che giấu chân thân, nhưng danh tính của nàng vẫn chưa được nói rõ."},{"chuong":722,"tieuDe":"Chuẩn Bị Tranh Tài Trăm Sông Tụ Biển","tomTat":"Tại Phù Phong thành, Thạch Hạo nhận ra Thanh Y chính là thứ thân Nguyệt Thiền từng thành thân với mình, nay đã che giấu dung mạo và gia nhập học viện Thiên Tiên. Thanh Y tiếp đón Mục Tử Tiêu cùng Tả Tiểu Địch của Thư viện Thần Nhai rồi đưa họ vào phủ đệ thương lượng. Thần Nhai muốn lấy manh mối Đại Xích Thiên hỏa để bồi dưỡng thiên kiêu trước khi vào di tích Tiên cổ, còn học viện Thiên Tiên cần tiên kim bảy màu để luyện bảy mũi tên cho Phượng Vũ. Sau khi Phượng Vũ tới dự, hai bên đạt thỏa thuận sơ bộ, nhưng Thần Nhai chỉ giao một khối khoáng thạch nhỏ còn Thiên Tiên chỉ cung cấp hướng tới một di tích nguy hiểm. Học viện Thiên Tiên sau đó treo thưởng cho đoàn lính đánh thuê và tán tu tìm vị trí tiên kim bảy màu, với phần thưởng là được ngâm một ngày một đêm trong hồ trồng Thần liên độ kiếp. Biết thần dược trong hồ có thể tái tạo huyết nhục và hỗ trợ vượt bình cảnh, Thạch Hạo động tâm vì đang giữ Kim Bồ quả nhưng chưa dám dùng. Những chuẩn bị của các đạo thống khiến hắn nhận ra đại chiến ba ngàn châu sẽ khốc liệt hơn dự tính, nên quyết định bắt đầu tích lũy cơ duyên và tiếp tục suy xét manh mối Hỗn Độn diễm tại Hỏa châu."},{"chuong":723,"tieuDe":"Quan Tài Đồng Nơi Vực Sâu","tomTat":"Thạch Hạo xác định Kim Bồ quả có thể giúp năng lực miễn dịch pháp lực tiến hóa cùng bản thân, nhưng hắn phải tìm cách hóa giải dược tính bá đạo không phù hợp với thể chất Nhân tộc. Tại thành Phù Phong, hắn từ chối lời mời của một ông lão thuộc đoàn lính đánh thuê Ma Phong và nhận ra đối phương chỉ muốn tuyển thêm người làm bia đỡ đạn trong hành trình tìm tiên kim bảy màu. Sau đó, hắn dùng một khối thần liệu đổi lấy chỗ ở trong một ngôi làng và nhờ dược lực còn lại của hạt bảo đan mà chữa khỏi thương thế sau năm ngày. Khi khôi phục trạng thái đỉnh cao, Thạch Hạo mang theo lò luyện đan, mặc giáp trụ rách nát rồi tiến xuống một vực sâu rộng hơn vạn dặm để tìm dấu vết Hỗn Độn diễm. Cuộc thăm dò dẫn hắn tới một phế tích mới trồi lên từ lòng đất và một thành cổ sụp đổ vẫn còn phù văn phát sáng. Trên đạo đài lớn như núi trong thành có chín bộ xương khổng lồ giống Chân Long, phía sau là quan tài đồng lớn chứa một quan tài đồng nhỏ. Khí hỗn độn tràn ra từ quan tài nhỏ khiến Thạch Hạo nghi ngờ Hỗn Độn diễm cùng một bí mật động trời đang ẩn bên trong."},{"chuong":724,"tieuDe":"Quan Tài Kỳ Lạ","tomTat":"Trong phế tích thành cổ dưới lòng đất, Thạch Hạo dò xét những tiếng động bí ẩn rồi tránh được một pho tượng phù văn mang thần uy sánh ngang Thiên Thần. Đạo đài cổ sụp đổ, khiến quan tài đồng cùng chín bộ khung xương khổng lồ chìm xuống giữa tòa thành chết. Thạch Hạo thử dùng cốt văn và sức mạnh thân thể mở quan tài nhỏ, nhưng pháp lực hoàn toàn vô hiệu còn nắp quan tài bị một lực lượng thần bí cưỡng ép đóng lại. Dị tượng từ quan tài đánh vào thức hải, cho hắn thấy một trận đại chiến làm nứt vỡ Đại Thiên thế giới, chín rồng kéo quan tài vượt dòng sông dài và một bóng người có thể là Liễu Thần. Khi máu hắn chạm vào quan tài, tiếng những cường giả vô thượng than khóc về tuổi thọ và minh ước vang lên, còn hắn vô thức tuyên bố sẽ mở một con đường cho họ. Không thể thu nhỏ hay mang quan tài đi, Thạch Hạo chuyển sang kiểm tra chín bộ xương được nghi là di cốt Chân Long. Đúng lúc hắn nghĩ đến việc tìm tủy rồng, một đám lửa lặng lẽ xuất hiện trong phế tích khiến hắn lập tức cảnh giác."},{"chuong":725,"tieuDe":"Bảo Hỏa","tomTat":"Trong cổ thành dưới lòng đất, Thạch Hạo chạm trán một ngọn bảo hỏa màu xanh thẳm mang đạo tắc đủ sức uy hiếp thần linh, nhưng bảo hỏa phù văn bên quan tài đồng xuất hiện và đánh lui nó. Hắn thử nghiên cứu quan tài cùng chín bộ khung xương, song không thể mở nắp, thu chúng vào bảo cụ hay phá vỡ khúc xương nghi chứa tủy rồng. Khi lục soát cổ thành, hắn làm vỡ một thế giới hộp quý đã mục nát, khiến phần lớn bảo tàng và hơn nghìn thần phù bị phá hủy, chỉ còn khối đá đen cực nặng cùng một nhóm bảo phù được bảo toàn. Trong số đó có Thần phù Bảo vệ, hai Phá giới phù, một Phá không phù và một tấm phù chưa rõ tác dụng. Thạch Hạo dùng Phá không phù chuyển quan tài đồng, chín bộ xương và bảo hỏa phù văn tới một không gian kín sâu dưới lòng đất, nhưng vẫn không thể thu phục ngọn lửa sau nửa tháng. Biết bảo hỏa xanh đã tiêu diệt một nửa nhân mã của hai nhóm giặc cỏ, hắn giữ Phá giới phù làm đường lui rồi quyết định tới Học viện Thiên tiên để tìm chất lỏng Thần liên độ kiếp, gặp Nguyệt Thiền thứ thân và nhắc lại giao ước với Phượng Vũ. Từ Phù Phong thành, hắn không dùng truyền tống trận mà bay thẳng tới thánh địa tu đạo này."},{"chuong":726,"tieuDe":"Thư Viện Thiên Tiên","tomTat":"Thạch Hạo tới vùng ngoại vi Thư viện Thiên Tiên ở biên giới Côn châu, đi qua các thành vệ tinh và khu chợ khổng lồ để tìm hiểu bảo dược, cốt thư cùng những bảo thuật quý hiếm đang được rao bán. Khi đến cổ môn, hắn chứng kiến dị tượng từ di tích tiên hiền, nơi một bóng người khổng lồ giảng đạo và mưa ánh sáng khiến thân thể, linh hồn của đám đông như được thanh lọc. Mọi người cho rằng Phượng Vũ đang tiến vào khu di khắc Chân Tiên để chuẩn bị cho đại quyết chiến thiên tài ba ngàn châu. Trước cửa thư viện, Trần Lâm và Ngô Phong dựa vào khí tức Liệt Trận cảnh mà Thạch Hạo cố ý để lộ để chế giễu, cho rằng hắn không đủ tư cách nhập học. Qua cuộc đối đáp, Thạch Hạo biết Thanh Y chính là Nguyệt Thiền và việc nàng vừa lọt bảng tuyệt sắc đã đẩy Trần Lâm xuống hạng mười một. Dù kỳ tuyển sinh đã kết thúc, hắn vẫn quyết định tìm hiểu thang trời, con đường giúp kỳ tài tuyệt thế được đặc cách trở thành đệ tử siêu tuyệt. Khi nghe người vượt qua còn được vào tiên trì gột rửa và có thể gặp các mỹ nhân trên bảng tuyệt sắc, phản ứng phấn khích của hắn khiến đám đông trước cửa lớn đồng loạt im lặng."},{"chuong":727,"tieuDe":"Mạnh Bạo Vượt Ải","tomTat":"Thạch Hạo công khai tuyên bố sẽ vượt thang trời để tiến vào tiên trì, bề ngoài còn đùa cợt về các mỹ nhân nhưng mục đích thật là lấy chất lỏng Thần liên độ kiếp để hỗ trợ ăn Kim Bồ quả. Hắn chấp nhận nguy cơ bị bá chủ nhận ra chân thân và chuẩn bị Phá giới phù làm đường lui. Tin khiêu chiến nhanh chóng lan khắp Thư viện Thiên Tiên cùng khu phố chợ, kéo đông đảo học sinh và tu sĩ tới quan sát. Ngô Phong chặn đường, nhưng chỉ một tiếng quát của Thạch Hạo đã khiến hắn phun máu và bay ngược. Bước vào cửa đầu, Thạch Hạo trở lại hình thái đứa trẻ rồi nâng tảng đá khoảng mười lăm đến mười sáu vạn cân qua đầu và đá nó nổ tung. Sang cửa thứ hai, ánh sáng từ thân thể hắn xuyên thủng mười Động thiên đạt cực hạn Nhân tộc. Tiếng chuông báo vượt cửa thứ ba, thứ tư và thứ năm liên tiếp vang lên, khiến những kỳ tài cùng mỹ nhân tuyệt sắc vốn xem nhẹ sự việc cũng phải vội vã chạy tới."},{"chuong":728,"tieuDe":"Bước Qua Thang Trời","tomTat":"Thạch Hạo dùng tu vi Tôn giả cảnh đối kháng xích thần trật tự tại cửa thứ sáu, cắt đứt toàn bộ pháp liên xâm nhập máu thịt và khiến tiếng chuông vượt ải vang khắp Thư viện Thiên Tiên. Thành tích ấy làm thái độ của nhiều người thay đổi, khiến Thiên Dao, Dạ Lăng Tuyết cùng đông đảo kỳ tài, giáo đầu và học sinh kéo tới quan sát. Tại cửa thứ bảy, hắn chịu uy thế tinh thần mang hình thái cự long và long trảo nhưng giữ vững thần thức, không lùi nửa bước. Sang cửa thứ tám, hắn đưa ra nhiều cách lý giải về Đạo rồi đá lăn ngọn đèn xanh, lấy chính hành động ấy làm câu trả lời và vẫn được công nhận vượt ải. Đối diện cửa xương cuối cùng cùng lời cảnh báo hình thần đều diệt, Thạch Hạo tiến vào không chút do dự, khiến cánh cửa tan vỡ và được xác nhận có đạo tâm kiên định. Sau khi hoàn thành toàn bộ chín cửa và phá vỡ lịch sử phủ bụi của thang trời, hắn không hỏi về truyền thừa mà nhắc lại chuyện được tắm cùng mười mỹ nhân, khiến toàn trường náo động."},{"chuong":729,"tieuDe":"Nhập Giáo","tomTat":"Thạch Hạo vượt qua cửa ải cuối của thang trời, khiến toàn bộ Thư viện Thiên Tiên chấn động và được xem là kỳ tài đủ sức bước vào hàng ngũ kế thừa đạo thống. Trên đài cao, hắn nhận ra Thanh Y chính là Nguyệt Thiền, còn những học sinh xung quanh liên tục trêu chọc hai người về chuyện đạo lữ và tiên trì. Một ông lão tóc bạc mặc đạo bào vàng đột ngột xuất hiện, khiến hai vị Thiên Thần rơi vào trạng thái như ngủ rồi mời Thạch Hạo gia nhập đạo trường của mình. Sau khi hứa cho hắn nhiều cơ hội vào Thần liên độ kiếp trì và gieo quẻ về nhân duyên, ông lão mở thông đạo hư không đưa hắn rời khỏi thư viện. Đạo chuông cửa ải thứ chín chỉ vang lên sau đó, khiến hai vị Thiên Thần tỉnh lại và nhận ra tiếng chuông trước đó đã bị áp chế. Báo cáo rằng người vượt Thiên quan không gia nhập thư viện cùng nghi vấn một nhân vật từng rời đi đã trở về khiến các chí cường giả trong viện đồng loạt kinh động. Cuối cùng, Thạch Hạo được đưa tới Đạo Tràng Chí Tôn, biết đây là truyền thừa đứng sau Cung điện Chí Tôn và chấp nhận trách nhiệm phải chiến đấu vì đạo trường."},{"chuong":730,"tieuDe":"Đạo Tràng Chí Tôn","tomTat":"Vì muốn tiếp cận Thần liên độ kiếp, Thạch Hạo chấp nhận gia nhập đạo thống do ông lão uy nghiêm giới thiệu và bị yêu cầu phải hướng tới vị trí xưng tôn thiên hạ. Hắn lập lời thề bằng tinh huyết, sau đó mới biết đoạn văn dùng trong nghi thức là lời nguyền trừng phạt người phản giáo. Ông lão tự xưng Tề Đạo Lâm, đưa Thạch Hạo quan sát sơn môn và tuyên bố toàn bộ thế giới đều có thể trở thành phạm vi của Đạo tràng Chí Tôn. Khi Tiên điện được nhắc tới, Tề Đạo Lâm nổi giận và công khai miệt thị thế lực này. Trở lại sơn môn, lão xác lập Thạch Hạo là truyền nhân duy nhất của đời này và yêu cầu hắn không nhận mình là đệ tử Thư viện Thiên Tiên. Biết đạo trường hiện chỉ có hai người, Thạch Hạo nghi mình đã mắc lừa nhưng vẫn quan tâm tới vô địch đạo mà Tề Đạo Lâm hẹn truyền sau hai ngày. Cuối cùng, hắn nhớ tới chín bộ long cốt và quan tài đồng cổ rồi hỏi liệu thế gian có người luân hồi hay không."},{"chuong":731,"tieuDe":"Bị Lừa","tomTat":"Tề Đạo Lâm bác bỏ khả năng một con người liên tục chuyển thế nhưng để ngỏ sự tồn tại của những chuyện xưa luân hồi, đồng thời khuyên Thạch Hạo tập trung vào hiện tại. Ông cho rằng Tiên đạo và Thần đạo cuối cùng cùng quy về một mối, rồi nghiêm túc dự báo đại loạn từ phương xa có liên quan tới sự bất diệt. Học viện Thiên Tiên phát hiện Thạch Hạo đã bị đưa đi nên các chí cường giả mở cửa hư không truy tới sơn môn, nhưng chỉ thấy môn khuyết và cung điện hiện nguyên trạng đổ nát. Vì học viện từng có lỗi với Tề Đạo Lâm và thực lực của ông đã tăng mạnh, Lão Viện trưởng quyết định từ bỏ việc tranh đoạt Thạch Hạo. Tại một vùng hoang mạc, Tề Đạo Lâm công bố Bát Cửu Thiên Công do mình sáng chế để khống chế nhiều bảo thuật, còn Thạch Hạo dù nghi bị lừa vẫn chọn học. Hắn bắt đầu nhập môn bằng cách gánh núi chạy hơn mấy vạn dặm mỗi ngày nhằm hợp nhất thân thể, pháp thuật và tinh thần. Cuối cùng, Tề Đạo Lâm đặt truyền nhân Tiên điện làm đối thủ chiến đấu công bằng đầu tiên và Thạch Hạo lập tức nhận lời."},{"chuong":732,"tieuDe":"Lai Lịch","tomTat":"Thạch Hạo đặc biệt chú ý tới hai chữ Bất hủ, nhưng Tề Đạo Lâm chỉ trầm mặc nhìn về tinh không mà không giải thích lai lịch của khái niệm này. Tề Đạo Lâm sau đó dùng Bát Cửu Thiên Công và lời cảnh cáo thanh lý môn hộ để ép đệ tử tiếp tục luyện thể bằng cách vác một ngọn núi chạy xuyên hoang mạc. Vì thân hình Thạch Hạo bị che khuất, các sinh linh chỉ thấy ngọn núi tự di chuyển và lưu truyền câu chuyện về một ngọn núi bay. Khi tới thảo nguyên giáp Hỏa châu và Thiên Tiên châu, hắn bị các học viên Học viện Thiên Tiên hiểu lầm là Sơn thần hoặc sơn bảo thông linh nên đồng loạt truy đuổi. Thạch Hạo hợp nhất thân thể, cốt văn và tinh thần, tăng tốc mang ngọn núi biến mất nơi chân trời. Sau ba ngày ba đêm khổ luyện, hắn kiệt sức, còn Tề Đạo Lâm cho phép nghỉ ngơi và nhấn mạnh rằng tu hành cần điều hòa giữa căng thẳng với thư giãn."},{"chuong":733,"tieuDe":"Truyền Nhân","tomTat":"Thạch Hạo biết mình đã bị Tề Đạo Lâm đưa vào một đạo trường suy tàn và bị nhiều thế lực khinh ghét. Nhóm học viên Học viện Thiên Tiên kể lại quá khứ Tề Đạo Lâm học truyền thừa từ nhiều đại giáo, đồng thời định làm theo lệ cũ để đánh đuổi truyền nhân mới. Thạch Hạo nhanh chóng trấn áp cả nhóm, bẻ sừng Lộc Minh, đánh bay Liễu sư huynh và chỉ tha Cảnh Tiểu Nhu vì nàng không có thành kiến với đạo trường. Hắn công khai tự xưng là Đại sư huynh của đạo trường Chí tôn, còn Tề Đạo Lâm tuyên bố sẽ bảo hộ đệ tử trước mọi thế lực. Sau đó, Thạch Hạo dựng bảng nhận đánh thuê trước cổng Học viện Thiên Tiên, gây sóng gió đến mức bị Tề Đạo Lâm gọi trở về. Khi biết mục tiêu của hắn là Thần liên độ kiếp, Tề Đạo Lâm trao một lệnh bài kim loại màu đen có thể thông hành tới thần trì. Nhờ tín vật này, Thạch Hạo chính thức tiến vào Học viện Thiên Tiên."},{"chuong":734,"tieuDe":"Đại Sư Huynh Đến Rồi!","tomTat":"Thạch Hạo nhận lời giúp một thiếu niên tán tu bị người Minh tộc bắt nạt, đánh gục nhóm tinh anh rồi công khai nhận nhiệm vụ đánh học viên để đổi lấy bảo dược hiếm. Vụ náo loạn khiến đội chấp pháp và nhiều học viên Học viện Thiên Tiên liên hệ hắn với truyền nhân Đạo trường Chí Tôn, từ đó quyết định tập hợp cao thủ vào núi thảo phạt vào ngày hôm sau. Trong lúc mọi người chuẩn bị đối phó mình, Thạch Hạo bí mật tiến vào học viện để tìm Thần liên độ kiếp. Nhờ địa đồ rách và lệnh bài kim loại màu đen do Tề Đạo Lâm giao, hắn vượt qua người canh giữ cùng hàng chục lớp trận pháp để tới khu vực sâu nhất. Trên đường đi, hắn dùng trùng đồng phát hiện một trùng Vương hình Huyết Hoàng và nghi đó là sinh vật Phượng Vũ từng mang khỏi Bí cảnh Nguyên Thiên. Tới tiên trì, Thạch Hạo bất ngờ thấy Nguyệt Thiền chuẩn bị xuống tắm, nhưng hắn thu liễm khí tức, chọn hướng khác xuống hồ rồi bơi về phía tỏa ra mùi thuốc."},{"chuong":735,"tieuDe":"Thần Liên Độ Kiếp","tomTat":"Thạch Hạo dùng lệnh bài kim loại màu đen xuyên qua đại trận, tiến vào vùng sâu của tiên trì Học viện Thiên Tiên và ẩn mình để tránh một nữ đệ tử đang rời hồ. Tại Tiểu thiên thế giới giữa hồ, hắn phát hiện Thần liên độ kiếp mang hình dạng một cổ thụ vàng khổng lồ, quanh thân có vô số lôi điện quấn lấy. Không thể vượt qua cốt văn phong tỏa nội hồ, hắn chuyển sang hấp thu thần dịch màu vàng hình thành khi Thần liên chín hòa vào nước quý. Thạch Hạo sau đó mạo hiểm luyện hóa Kim Bồ quả, nhưng độc tính và đạo tắc trong quả liên tục phá hủy thân thể, nguyên thần cùng Đạo tâm của hắn. Nhờ vận chuyển Nguyên Thủy Chân Giải và dùng thần dịch chữa trị, hắn sống sót qua nhiều lần thân thể nổ tung và luyện hóa được ba phần tư quả. Năng lực miễn dịch pháp lực của hắn trở nên rõ ràng hơn, đồng thời xuất hiện dấu hiệu có thể tiếp tục trưởng thành theo tu vi. Ở phía bên kia Thần liên, một thiếu nữ đang tắm bảo dịch đã cảm nhận được gợn sóng trật tự thần bí do quá trình luyện hóa gây ra."},{"chuong":736,"tieuDe":"Sự Cuốn Hút Trong Tiên Trì","tomTat":"Thạch Hạo tiếp tục luyện hóa Kim Bồ quả trong tiên trì, chịu cảnh dược lực và xích thần trật tự liên tục xé nát xương thịt, thậm chí làm đứt cánh tay và tổn thương trái tim. Hắn vận dụng Luân Hồi để ảnh hưởng thời gian, đồng thời hấp thu thần dịch màu vàng từ Thần liên độ kiếp nhằm tái sinh thân thể và vượt qua hơn mười lần tan rã. Sau khi hấp thu hết dược tính, Thạch Hạo gần như cạn sạch tinh khí nhưng năng lực miễn dịch pháp lực được củng cố rõ rệt. Ở phía đối diện, Nguyệt Thiền cảm nhận dao động bất thường, tiến đến điều tra và phát hiện một nam học viên xuất hiện trong ngày dành riêng cho nữ học viên. Nàng mặc chiến giáp cấp thần, triển khai công kích thần thức, sức mạnh nguyền rủa và năm loại bảo thuật để phong tỏa Thạch Hạo. Các bảo thuật đều bị năng lực miễn dịch pháp lực hóa giải, buộc Nguyệt Thiền phải áp sát. Chương kết thúc khi hai người khóa tay nhau và chuyển sang giao đấu cận chiến, trong lúc Thạch Hạo vẫn giữ Phá giới phù làm đường lui."},{"chuong":737,"tieuDe":"Thân Phận Bị Tiết Lộ","tomTat":"Nguyệt Thiền dùng Chiến Thiên thuật đã được chú ngôn gia trì tấn công Thạch Hạo, nhưng năng lực miễn dịch pháp lực từ Kim Bồ quả giúp hắn hóa giải bảo thuật. Hai người chuyển sang quyết chiến cận thân bằng Chân long, Tiên hoàng và nhiều thủ đoạn khác, trong khi Thạch Hạo dùng pháp môn Côn Bằng biến dị cùng Kim Tuyền Ba Văn công hút tinh khí và bảo dịch của Thần liên độ kiếp để phục hồi. Khi Nguyệt Thiền triển khai Dao thần thức uy hiếp nguyên thần, Thạch Hạo tái kích phát miễn dịch pháp lực rồi dùng Động thiên duy nhất và cốt văn của Nguyên thủy chân giải phong ấn nàng. Hạt Kim Bồ quả bất ngờ nứt ra, giải phóng một hạt xanh biếc xâm nhập cơ thể, khiến thân thể, xương trán và nguyên thần Thạch Hạo gần tan rã. Hắn vận dụng cảm ngộ Hóa Linh, phân giải sức mạnh tinh thần thành nhiều thánh vật và phối hợp Nguyên thủy chân giải để tạm cân bằng sức phá hoại với sinh cơ. Nguyệt Thiền nhờ đã đề phòng thủ đoạn từng áp chế mình ở hạ giới nên tự giải được phong ấn và nhận ra thân phận thật của Thạch Hạo. Tuy có cơ hội ra tay khi hắn suy yếu, nàng không biểu lộ sát khí, khiến Thạch Hạo trực tiếp đề nghị nàng giúp đỡ."},{"chuong":738,"tieuDe":"Dùng Thân Báo Đáp","tomTat":"Dược lực từ hạt Kim Bồ quả khiến thân thể và nguyên thần Thạch Hạo đứng bên bờ tan rã, buộc hắn phải cầu Nguyệt Thiền cứu giúp. Nguyệt Thiền không nhân cơ hội sát hại hắn mà truyền lực lượng chữa lành thân thể, sau đó dùng ánh sáng tinh thần từ dấu ấn Tiên hình để ổn định nguyên thần. Nhờ sự trợ giúp ấy cùng chất lỏng vàng do Thần liên độ kiếp tiết ra, Thạch Hạo luyện hóa hoàn toàn Kim Bồ quả và hạt giống, đồng thời hiểu được phần quả tạo bí lực miễn dịch pháp lực còn hạt giúp năng lực này tiếp tục sinh trưởng. Xương cốt, huyết nhục và cốt văn của hắn được tái tạo, đưa cơ thể trở lại trạng thái hoàn chỉnh và khôi phục hình dáng thật. Thạch Hạo xem năng lực miễn dịch pháp lực là một đòn sát thủ, đồng thời mong chờ cuộc tranh bá giữa các kỳ tài tại đại chiến ba ngàn châu. Khi Nguyệt Thiền không đưa ra điều kiện báo đáp, hắn đùa rằng sẽ lấy thân báo đáp rồi kết hợp pháp môn Côn Bằng với Súc địa thành thốn để áp sát và nắm tay nàng không buông."},{"chuong":739,"tieuDe":"Ước Định","tomTat":"Thạch Hạo tiếp tục trêu chọc Nguyệt Thiền về việc hai người từng bái đường ở hạ giới, nhưng cuối cùng nàng chủ động đề nghị bỏ qua những hiềm khích cũ. Sau khi nghe hắn kể hành trình tại thượng giới, Nguyệt Thiền nhận ra hắn chính là Hoang và tiết lộ mình đang né tránh chủ thân có thần thức niết bàn bẩm sinh. Nàng hứa sẽ thừa nhận hôn sự năm xưa nếu Thạch Hạo thắng đại chiến thiên tài ba ngàn châu. Từ mô tả về ngọn lửa xanh tại Hỏa châu, nàng xác định đó là Thanh Nguyệt diễm, giải thích lời đồn về nguồn gốc Chân tiên của các bảo hỏa hi thế và cho biết tiên hiền từng tổng kết bí pháp thu phục ngọn lửa. Hai người hẹn vài ngày sau cùng đến Hỏa châu hành động. Khi rời tiên trì, Thạch Hạo công khai gọi Thanh Y là vợ rồi dùng lệnh bài kim loại màu đen rời đi, khiến Học viện Thiên Tiên náo loạn và Đạo trường Chí Tôn bị đòi chinh phạt. Trở về sơn môn, hắn hỏi Tề Đạo Lâm về quan tài đồng cổ cùng chín con rồng, khiến vị đạo chủ lập tức đứng bật dậy và không thể giữ bình tĩnh."},{"chuong":740,"tieuDe":"Một Đám Biến Thái","tomTat":"Thạch Hạo dò hỏi Tề Đạo Lâm về chín rồng kéo quan tài đồng và được biết vật ấy mang tên Tam thế đồng quan, một chí bảo thần bí bắt nguồn từ Tiên cổ, ngay cả cường giả đỉnh cao cũng có thể chết nếu cố mở. Tề Đạo Lâm kể rằng một lão nhân vô thượng thuộc sư môn mình từng dành nửa đời truy tìm cổ quan, nhưng bị tổn thương đạo cơ khi đẩy nắp rồi chết trong cuộc vây quét do cường giả Tiên điện phát động. Nhận ra đây là khúc mắc sâu sắc của Tề Đạo Lâm, Thạch Hạo quyết định tạm giấu trải nghiệm và vị trí Tam thế đồng quan để chờ lão bình tĩnh. Khi hỏi cách hàng phục thần diễm hi thế để thành Thần, hắn được yêu cầu phải tiến vào tốp mười đại chiến ba ngàn châu, nếu không sẽ bị thanh lý môn hộ. Tề Đạo Lâm cảnh báo truyền nhân Tiên điện chưa phải mối đe dọa lớn nhất, bởi nhiều chí tôn trẻ tuổi từng đứng đầu các thời đại trước đang tự phong dưới núi băng và hang tuyết để chờ tranh đoạt tạo hóa Tiên cổ. Lời đồn về một sinh linh đã tham dự mười kỳ đại chiến và cả mười lần đứng đầu khiến Thạch Hạo thực sự cảm nhận được áp lực từ đội ngũ đối thủ sắp xuất thế."},{"chuong":741,"tieuDe":"Đối Thủ Đáng Sợ","tomTat":"Thạch Hạo thắc mắc vì sao những người từng đứng đầu đại quyết chiến ba ngàn châu vẫn có thể tiếp tục dự tuyển dù cửa vào chỉ cho phép tu sĩ không vượt quá Tôn giả cảnh. Tề Đạo Lâm giải thích rằng các thiên tài ấy đã tự phế tu vi sau khi bước vào Thần Hỏa cảnh, thậm chí có người chém bản thân xuống Bàn Huyết cảnh rồi trùng tu nhiều lần để liên tục củng cố căn cơ thần đạo. Dù được khuyên phải ưu tiên giữ mạng, Thạch Hạo vẫn tin các cảnh giới hoàn mỹ của mình đủ sức đối đầu những đối thủ đáng sợ đó. Tề Đạo Lâm truyền cho hắn Dục Hỏa thuật, Tầm Hỏa thuật, Tế Hỏa đạo và ngôn ngữ tế tự Tiên cổ, đồng thời chỉ rõ người tu nên giao lưu và giành sự công nhận của cổ hỏa thay vì cưỡng ép hàng phục. Lão còn nhận định những mồi lửa đứng đầu có thể là di sản do Chân tiên để lại, trong đó Thanh Nguyệt diễm có khả năng bắt nguồn từ nữ tiên Thanh Nguyệt và mạnh ngang Đại Xích Thiên hỏa. Sau năm ngày bế quan củng cố các phương pháp mới học, Thạch Hạo tới Học viện Thiên Tiên tìm Nguyệt Thiền để bắt đầu thử thu Thanh Nguyệt diễm, đồng thời dự tính sau đó sẽ tiếp cận mồi lửa thần bí trong quan tài đồng."},{"chuong":742,"tieuDe":"Nắm Tay Nhau Cùng Đi","tomTat":"Học sinh Học viện Thiên Tiên nhận ra Thạch Hạo là truyền nhân Đạo trường Chí Tôn nên đuổi theo, nhưng hắn nhanh chóng cắt đuôi và dùng lệnh bài đặc biệt vượt qua trận pháp khu nữ sinh. Tại linh sơn của Nguyệt Thiền, hắn hội ngộ nàng, vừa trêu ghẹo vừa bàn cách thu lấy Thanh Nguyệt diễm rồi cùng nàng rời học viện. Trong khi những người truy đuổi tranh cãi về thân phận thật của Thạch Hạo, một nhóm khác kéo tới phế tích Đạo trường Chí Tôn để vây quét. Hai người tiến vào đại thảo nguyên Hỏa châu, nơi Nguyệt Thiền kể về tiên quáng bảy màu nguy hiểm và nhu cầu tiên kim của Phượng Vũ. Họ xuống một hẻm núi hoang vu, xuyên qua khe đất và tiến vào phế tích Tiên cổ nằm sâu dưới lòng đất. Tại đó, Thạch Hạo và Nguyệt Thiền phát hiện vầng trăng xanh chính là Thanh Nguyệt diễm, nhưng ánh sáng nóng rực của cổ hỏa lập tức thiêu y phục của cả hai thành tro."},{"chuong":743,"tieuDe":"Thanh Nguyệt","tomTat":"Ánh sáng từ Thanh nguyệt thiêu sạch y phục của Thạch Hạo và Nguyệt Thiền, khiến Thạch Hạo nhân cơ hội trêu chọc và bám sát nàng. Khi hai người triệu pháp khí để phòng hộ, Thanh nguyệt phóng ánh sáng nung chảy chiếc roi thần của Thạch Hạo và phá hủy giáp trụ Thần cấp của Nguyệt Thiền. Thạch Hạo dùng ngôn ngữ cúng tế Tiên cổ để nhận biết rằng mồi lửa chỉ cảnh cáo họ không được làm bậy, còn binh khí và giáp trụ bị hủy vì bị coi là hành động khiêu khích. Hai người sau đó trao đổi đạo tế hỏa cùng những phần cổ ngữ khác nhau mà mình nắm giữ, nhờ đó hoàn thiện phương thức giao tiếp với mồi lửa. Nguyệt Thiền chủ trì tụng lời cúng tế trong khi Thạch Hạo hộ pháp, khiến Thanh Nguyệt diễm hạ xuống đỉnh đầu nàng và gần thiết lập quan hệ thân thiết. Chứng kiến tiến triển ấy, Thạch Hạo bắt đầu dự tính tìm một loại cổ hỏa còn thần bí hơn cho bản thân."},{"chuong":744,"tieuDe":"Tiên Ảnh","tomTat":"Thanh Nguyệt diễm từ từ hạ xuống, buộc Nguyệt Thiền dùng ngôn ngữ cúng tế Tiên cổ để thiết lập cộng hưởng trong khi Thạch Hạo truyền tinh hoa bản nguyên hỗ trợ nàng. Khi cổ hỏa chỉ còn cách khoảng một thước, một tiên ảnh thướt tha bất ngờ hiện lên bên trong Thanh nguyệt, khiến quá trình tiếp nhận chuyển thành biến cố chết người. Ánh trăng xanh xâm nhập huyết nhục, đốt cả thần hồn và đẩy Nguyệt Thiền tới sát bờ hình thần đều diệt. Thạch Hạo bất chấp nguy hiểm, mặc giáp trụ rách nát lao vào cứu nàng, chuyển giáp sang bảo vệ nàng rồi lấy lò luyện đan chuẩn bị vận dụng những thủ đoạn cuối cùng. Thanh nguyệt chỉ đẩy hắn ra mà không gây thêm thương tích, còn tiên ảnh dường như phát ra một tiếng thở dài. Ngay sau đó, cổ hỏa nghịch chuyển từ hủy diệt sang tái sinh, khôi phục sinh cơ và tái tạo thân thể Nguyệt Thiền. Dấu ấn nghi là Thần hình Tiên đạo tại mi tâm nàng cũng hóa thành bóng nữ tử nhảy múa, cộng hưởng với dấu ấn nữ tiên trong Thanh nguyệt."},{"chuong":745,"tieuDe":"Đạo Chủng Mồi Lửa","tomTat":"Nguyệt Thiền vượt qua nguy hiểm và hoàn thành khế ước với Thanh Nguyệt diễm, khiến cổ hỏa hóa thành bảo y rồi hợp nhất với dấu ấn tại mi tâm. Sau khi tỉnh lại, nàng bàn với Thạch Hạo về đại chiến thiên tài ba ngàn châu, còn hai người lập ước định rằng hắn sẽ đưa nàng về nếu giành được vị trí đệ nhất thiên hạ. Nguyệt Thiền giải thích bảo hỏa hi thế có thể trở thành tiên chủng và mồi lửa giúp người tu hành sớm nhìn thấy con đường thành thần. Thạch Hạo nghi ngờ sự phụ thuộc vào cổ hỏa, đề xuất lấy vạn vật thiên địa làm đối tượng học hỏi và tự đốt cháy bản thân để mở ra con đường riêng. Ngay sau lời luận đạo, một tia sét từ hư không đánh trúng hắn, nhưng thân thể cường đại giúp hắn chỉ bị cháy khét và thương thế không nghiêm trọng. Khi hai người trở về Học viện Thiên Tiên, đạo chuông của học viện cùng tiếng chuông từ Côn châu và Hỏa châu lần lượt vang lên. Nguyệt Thiền nhận định hiện tượng vạn chuông cùng ngân báo hiệu đại chiến thiên tài ba ngàn châu sắp bắt đầu."},{"chuong":746,"tieuDe":"Lần Đầu Hành Động","tomTat":"Sau khi các giáo và đại tộc mạnh nhất thống nhất quyết định, chuông lớn đồng loạt vang khắp ba ngàn châu, báo hiệu giai đoạn chuẩn bị cho đại chiến thiên tài và cơ duyên Tiên cổ. Nguyệt Thiền hóa thành Thanh Y trở về Học viện Thiên Tiên, còn Thạch Hạo gặp Tề Đạo Lâm và thừa nhận đã tặng Thanh Nguyệt diễm cho người khác. Tề Đạo Lâm giải thích vai trò của Tiên chủng khi nhen lửa thành Thần, định đoạt Đại Xích Thiên hỏa cho đệ tử nhưng bị từ chối, rồi tiếp tục bắt hắn cõng núi rèn nền tảng Bát Cửu Thiên Công. Trong lúc suy nghĩ về con đường Loại đạo, Thạch Hạo đâm vào dãy núi và khiến người của học viện tưởng ngọn núi đang chạy là sơn thần hoặc bảo cụ thông linh. Khi bị nhận diện và chế giễu, hắn tay không phá nát toàn bộ bảo cụ của nhóm người truy đuổi, đánh họ tan tác và đá bay một hậu duệ Hoàng tộc Thiên Nhân. Tại điện phủ Học viện Thiên Tiên, Mạc Khôn công khai hạ thấp Hoang và xuyên tạc biến cố giữa hắn với Thiên Nhân tộc. Thanh Y chất vấn việc Thiên Nhân tộc mơ ước bảo thuật rồi lấy oán báo ân, khiến Mạc Khôn né tránh bằng cách nhắc U Vũ cùng Vân Hi có thể sắp tới Hỏa châu."},{"chuong":747,"tieuDe":"Khởi Binh Hỏi Tội","tomTat":"Mạc Khôn tuyên bố U Vũ có thể tới Học viện Thiên Tiên và hết lời đề cao vị sơ đại đã dung hợp Thiên Mệnh thạch, tin rằng người này đủ sức trấn áp Hoang. Phượng Vũ thận trọng phản bác bằng những chiến tích Thạch Hạo từng giết Minh Tử, chém Thái Dương thần đằng và hầm chín sinh linh Tử Kim của Chân Hống tộc. Khi biết một tu sĩ Thiên Nhân tộc bị đệ tử của đạo tràng suy tàn đánh thương, Mạc Khôn quyết định dùng uy thế của tộc tới khởi binh hỏi tội, trong khi Nguyệt Thiền cố ý che giấu thân phận và thực lực của đối thủ. Đoàn người đi qua con đường đầy cỏ dại tới sơn môn gần như chỉ còn phế tích, khiến Mạc Khôn càng thêm khinh miệt. Thạch Hạo đang khó chịu vì bị Tề Đạo Lâm quở trách nên lập tức ra tay, kết hợp pháp thuật Côn Bằng với Súc địa thành thốn rồi bí mật dùng Động Thiên duy nhất giam cầm Mạc Khôn. Hắn tiếp tục dùng sức mạnh thân thể đánh đối phương gãy nhiều xương, rụng sạch răng và mất khả năng chống trả. Sau khi ném Mạc Khôn xuống đất, Thạch Hạo mới hỏi hắn là ai và đến từ bộ tộc nào."},{"chuong":748,"tieuDe":"Nhằm Vào Thiên Nhân Tộc","tomTat":"Mạc Khôn dựa vào uy danh Thiên Nhân tộc để đe dọa Thạch Hạo, nhưng hành động này chỉ khơi lại mối thù do Thạch Hạo từng bị tộc ấy giam giữ và mưu đoạt bảo thuật. Thạch Hạo đánh gãy chân, phá cằm, nghiền nát xương cốt rồi dùng lôi điện phế bỏ toàn bộ đạo hạnh của Mạc Khôn. Một người thuộc mạch Cửu Đầu xà lên tiếng can thiệp cũng bị bảo thuật Lôi đế đánh cháy đen, sau đó Thạch Hạo vận Kim Tuyền Ba Văn công bổ sung chân nguyên và phóng hàng vạn tia điện đánh ngã những cường giả trẻ tuổi mang địch ý. Hắn công khai tuyên bố sẽ đánh cả sáu kiệt Thiên Nhân tộc và ở lại sơn môn chờ U Vũ, Vân Hi cùng những cao thủ khác tới. Khi Thạch Hạo thú nhận mình đang bị các giáo truy tìm, Tề Đạo Lâm cho biết ông đã biết chuyện này từ trước khi thu hắn làm đệ tử ký danh. Cuối cùng, Tề Đạo Lâm cho phép Thạch Hạo lên đường đánh phá các đạo tràng và quặng mỏ bên ngoài của Thiên Nhân tộc tại Hỏa châu."},{"chuong":749,"tieuDe":"Tạo Hóa","tomTat":"Thạch Hạo nhận thấy Tề Đạo Lâm dường như đã biết lai lịch hạ giới của mình nhưng luôn cắt ngang, không để hắn nói rõ thân phận. Sau khi rời Đạo trường Chí Tôn, hắn dùng tư liệu lấy từ Nguyệt Thiền để điều tra hai khu mỏ lớn của Thiên Nhân tộc gần Thiên Tiên châu, trong khi việc đạo trường tái xuất khiến các giáo nhớ lại quá khứ tai tiếng của Tề Đạo Lâm. Tại một mỏ cổ, Thạch Hạo dùng trùng đồng phát hiện dao động đại đạo và sương trắng dưới lòng đất, đồng thời nhận ra số Chân Thần canh giữ nhiều bất thường. Nghe lén cuộc trò chuyện của họ, hắn biết U Vũ vừa dung hợp Thiên Mệnh thạch và sắp được Thiên Thần hộ tống tới đây, còn mục đích thật liên quan đến một tảng đá có thể chứa Tiên chủng hoặc Đạo chủng tiên huyết. Thạch Hạo tạm bỏ kế hoạch tấn công thông thường, kết hợp pháp thuật Côn Bằng với Súc địa thành thốn để lẻn sâu vào mỏ. Sau một ngày một đêm ẩn nhẫn, hắn chớp lúc các Chân Thần đổi ca và nâng tảng đá dài khoảng bốn trượng lên. Khí tức đại đạo cùng vô tận mẫu khí trời đất lập tức bùng phát, khiến hắn xác định vật bên trong là báu vật đủ làm Thiên Nhân tộc phát cuồng."},{"chuong":750,"tieuDe":"Trời Đất Sinh Ra","tomTat":"Thạch Hạo cõng tảng đá kỳ lạ chạy khỏi khu vực sâu trong mỏ quặng cổ của Thiên Nhân tộc, trong khi các Chân Thần nhận ra mẫu khí quanh nó và tin rằng bên trong đang thai nghén một kỳ vật vô thượng. Mười một Chân Thần phối hợp cốt văn, pháp khí, cấm chế và trận pháp bí ẩn để vây bắt hắn, nhưng sự kiêng dè đối với vật trong đá khiến họ nhiều lần không dám dốc toàn lực. Thạch Hạo dùng Súc địa thành thốn và thân pháp Côn Bằng xuyên qua vòng phong tỏa, đồng thời kích hoạt thần phù lấy từ phế tích Tam thế đồng quan để chặn những đòn đánh trực diện. Sau khi hắn thoát lên đồng cỏ, kỳ thạch đột ngột trở nên cực nặng rồi vỡ thành bốn mảnh, giải phóng khí tức đại Đạo làm hư không rạn nứt, khiến nhiều Chân Thần bị thương và thần phù hộ thân xuất hiện một vết nứt rõ ràng. Một kỳ vật được mẫu khí bao phủ rơi ra từ khối đá, liên tục biến đổi kích thước trước khi bị Thạch Hạo nhanh tay nhặt lấy. Hắn dùng Phá không phù phối hợp Súc địa thành thốn và pháp môn Côn Bằng để thoát khỏi toàn bộ truy binh, đồng thời giữ lại hai tấm Phá giới phù cho tình huống nguy cấp hơn."},{"chuong":751,"tieuDe":"Vật Thần Thánh","tomTat":"Mười mấy Chân Thần Thiên Nhân tộc tìm kiếm quanh thảo nguyên nhưng không thu hồi được vật thần thánh, rồi dựa vào Súc địa thành thốn và pháp môn Côn Bằng để xác định kẻ cướp chính là Hoang. Trong khi đó, Thạch Hạo đã chạy xa vạn dặm và bắt đầu nghiên cứu vật vừa đoạt được, phát hiện bên ngoài là mẫu khí trời đất còn bên trong có hình dạng giống một quả trứng với dấu ấn đại Đạo trên vỏ. Hắn nảy ý tưởng không dùng thần hỏa của người xưa mà lấy toàn bộ thế giới làm lò, lấy đạo tắc chư thiên làm lửa để rèn luyện bản thân khi thành Thần. Thạch Hạo đem vật về hỏi Tề Đạo Lâm và được biết bên trong quá nửa là Tiên kim, còn giá trị cốt lõi nằm ở cuống rốn do mẫu khí cùng lớp vỏ tạo thành, có khả năng liên thông vạn Đạo. Tề Đạo Lâm cảnh báo con đường này chưa từng có ai thành công, tỷ lệ thành công thông thường chỉ khoảng hai phần, còn kết quả tốt nhất cũng chỉ đạt bốn phần mười. Nếu thành công, Tiên kim có thể cộng sinh với Thạch Hạo thành một vũ khí được trời đất rèn đạo ngân, nhưng nếu thất bại thì Tiên kim sẽ bị phế và hắn cũng hóa thành tro tàn."},{"chuong":752,"tieuDe":"Con Đường Khác Nhau","tomTat":"Dù Tề Đạo Lâm cảnh báo con đường vượt khỏi lối tu hành cũ gần như chắc chắn dẫn tới cái chết, Thạch Hạo vẫn quyết tâm tiếp tục tìm tòi. Tề Đạo Lâm giao cho hắn kho cốt thư lấy từ nhiều đại giáo, qua đó hé lộ những thất bại của Côn Vũ, Ngũ Hoàng và các kỳ tài cổ đại từng thử đi con đường khác. Sau khi nghiên cứu, Thạch Hạo quyết định đưa vật thần thánh hình bầu dục chứa tiên kim vào thức hải để nguyên thần sớm cảm ứng các Đạo tắc. Mẫu khí bao quanh vật này bất ngờ bạo động, làm xương trán hắn rạn nứt, buộc Tề Đạo Lâm dùng bản thô Bát Cửu Thiên Công phối hợp Pháp thuật Côn Bằng và Bảo thuật Lôi Đế để trấn áp. Biến động trong thức hải kích hoạt dược lực Kim Bồ quả còn tích lại, khiến thần thức Thạch Hạo lớn mạnh và nguyên thần lột xác thành một hình người rực rỡ. Sự biến đổi ấy kéo theo tích lũy toàn thân bùng phát, giúp hắn đột phá lên Tôn giả cảnh hậu kỳ."},{"chuong":753,"tieuDe":"Tắm Máu Thiên Nhân Tộc","tomTat":"Thạch Hạo hoàn tất đột phá tại Tôn giả cảnh, khiến tinh lực và huyết khí hóa thành dị tượng Chân Long làm rung chuyển sơn môn, đồng thời nhận được lời tán thưởng hiếm hoi của Tề Đạo Lâm. Sau khi tiên chủng trong kỳ thạch biến mất khỏi cổ quáng Hỏa châu, Thiên Nhân tộc điều hai Thiên Thần lục soát đại thảo nguyên và gây sức ép với Khổng Tước tộc, Hỏa tộc cùng các đạo thống có nguồn gốc hạ giới. Tại Phù Phong thành, Thạch Hạo nhận ra đối phương đang che giấu thân phận thật của Hoang để độc chiếm truyền thừa, đồng thời dùng những thế lực liên quan tới hạ giới để ép hắn xuất hiện. Hắn lập tức công khai thân phận Hoang và tiến đánh các mỏ quặng của Thiên Nhân tộc. Nhờ năng lực miễn dịch pháp lực kéo dài hơn trước, Thạch Hạo dùng tay không phá pháp khí cấp Thần, giết hơn mười cường giả Thần Hỏa cảnh và đánh sập tám mỏ quặng. Tin tức truyền về Phù Phong thành khiến Hỏa châu chấn động, biến cuộc truy lùng sai hướng của hai Thiên Thần thành trò cười và khơi dậy sự cổ vũ công khai dành cho Hoang."},{"chuong":754,"tieuDe":"Giết Chóc Bốn Phương","tomTat":"Tin tức truyền về Phù Phong thành cho biết Hoang đã liên tiếp đánh phá các thần quáng của Thiên Nhân tộc, khiến thanh danh của bộ tộc này bị đe dọa nghiêm trọng. Thạch Hạo tập kích một đạo tràng đang thiếu Chân Thần trấn giữ, đánh bại bốn cường giả Thần Hỏa cảnh và san bằng toàn bộ cung điện. Người báo tin xác nhận hắn chính là người lấy tiên trân và đã phá hủy mười bốn mỏ quặng, tương đương khoảng một phần ba số thần quáng nổi tiếng của Thiên Nhân tộc. Các Chân Thần lập tức phát lệnh vây quét trên toàn thảo nguyên, nhưng Thạch Hạo lợi dụng mưa bão và bóng tối để né tránh rồi tiếp tục đánh du kích. Cuối cùng, hắn tới mỏ quặng lớn nhất và chủ động đối đầu ba Chân Thần trấn thủ. Nhờ điều kiện lôi vân tự nhiên, Thạch Hạo thi triển Lôi động cửu thiên của bảo thuật Lôi Đế, dẫn thiên uy vượt quá cực hạn bản thân và đánh chết cả ba Chân Thần."},{"chuong":755,"tieuDe":"Sóng Gió Và Chú Ý","tomTat":"Sau khi phá hủy hơn nửa mỏ quặng lớn nhất của Thiên Nhân tộc và khiến ba Chân Thần bị tiêu diệt, Thạch Hạo lập tức rời đại thảo nguyên trước khi hai Thiên Thần kịp phản ứng. Tin chiến tích của Hoang truyền qua Phù Phong thành tới nhiều đại giáo trong mấy chục châu, khiến một số thế lực muốn chiêu mộ và bảo vệ hắn để đối đầu Thiên Nhân tộc trong tương lai. Hai Thiên Thần đang gây sức ép với Hỏa tộc phải chịu chế nhạo, rút khỏi khu mỏ và quyết tâm giết hắn trước khi hắn trưởng thành. Tại Học viện Thiên Tiên, học sinh náo động bàn luận về Hoang mà không nhận ra Thạch Hạo đang xuất hiện ngay trước mắt. Bên hồ, Nguyệt Thiền hỏi Vân Hi về lời đồn Hoang từng hộ tống nàng hàng trăm nghìn dặm và giao chiến với Chiến tộc, còn Thạch Hạo lặng lẽ quay đi sau khi bị hai người phát hiện bóng lưng. Khi nghe một số thành viên Lục kiệt muốn lên Đạo trường Chí Tôn đòi lời giải thích, Thạch Hạo công khai tuyên bố sẽ tiêu diệt bất cứ ai dám tới sơn môn khiêu chiến."},{"chuong":756,"tieuDe":"Tương Lai Không Tốt","tomTat":"Thần quáng đệ nhất của Thiên Nhân tộc bị phá hủy, ba Chân Thần bị đánh gục và tiên chủng mất tích, khiến hai Thiên Thần nổi giận vì Hoang đã thoát khỏi vòng vây. Mạc La thông báo người Hộ đạo gần cạn thọ nguyên sẽ dùng sinh mệnh cuối cùng để bói toán vị trí và quỹ tích của Hoang, cho thấy bộ tộc lo sợ một tương lai bất lợi do hắn gây ra. Thiên Nhân tộc lập tức huy động toàn bộ lực lượng cùng các đạo thống, môn phái và chủng tộc có giao tình để truy sát, nhưng vẫn che giấu việc Hoang chính là Thạch Hạo nhằm độc chiếm bảo thuật của hắn. Biết thân phận có thể sắp bại lộ, Thạch Hạo không sợ hãi mà xác lập chí hướng trở nên đủ mạnh để không ai còn có thể làm nhục, giam cầm hay cướp đoạt truyền thừa của mình. Tại Học viện Thiên Tiên, Vũ Luân phẫn nộ trước thất bại của bộ tộc và muốn trút giận lên đại sư huynh của đạo tràng nhỏ. Bất chấp lời can ngăn của người đứng thứ sáu trong Lục kiệt, hắn dựa vào vũ khí bí mật do Thiên Thần ban xuống, gọi giao thú trắng và lên đường khiêu chiến."},{"chuong":757,"tieuDe":"Tiểu Thạch Phát Uy","tomTat":"Tin Vũ Luân muốn giao chiến gây chấn động Học viện Thiên Tiên, khiến đông đảo học sinh cùng những người từ các thế lực khác kéo tới Đạo tràng Chí Tôn quan chiến. Vũ Luân cưỡi giao thú vượt ba nghìn dặm, tuyên bố sẽ đạp nát ngọn núi và chém đầu Thạch Hạo để rửa nhục cho Thiên Nhân tộc. Trước sơn môn, hắn hợp lực với tọa kỵ, vận chuyển cốt văn và dốc toàn bộ thần thông, bảo thuật vào một đòn quyết định sinh tử. Thạch Hạo ngưng tụ lôi điện thành giáp trụ cùng chiến mâu vàng, đánh văng Phương Thiên Họa kích rồi xuyên thủng ngực Vũ Luân. Vũ Luân nhận ra đối thủ có thể là Hoang và định điều khiển bí bảo phản kích, nhưng bị chiến mâu chấn vỡ thân thể, chết ngay tại chỗ. Một thành viên khác trong Lục kiệt Thiên Nhân tộc tới cứu viện cũng bị Thạch Hạo dùng chiến mâu kết hợp phù văn Lôi Đế và Côn Bằng xuyên thủng rồi đánh nổ giữa trời. Hai cái chết liên tiếp khiến toàn bộ người chứng kiến kinh hãi, còn thân phận Hoang của Thạch Hạo bắt đầu đứng trước nguy cơ bị nhận ra."},{"chuong":758,"tieuDe":"Bão Táp","tomTat":"Dư âm trận chiến tại Đạo tràng Chí Tôn khiến đám đông chấn động khi Thạch Hạo dùng một mâu giết Vũ Luân cùng người tới cứu viện, làm Thiên Nhân tộc mất hai thành viên Lục kiệt. Từ di vật của Vũ Luân, Thạch Hạo thu được Phù triện Thiên Thần, một sát khí có thể uy hiếp Chân Thần nhưng chưa kịp được đối thủ sử dụng. Tin dữ truyền tới Học viện Thiên Tiên khi U Vũ đang luận bàn di khắc Nhân Tiên với Phượng Vũ, khiến học sinh và các đại giáo đồng loạt náo động. Tại Hỏa châu, Mạc La cầu viện Độc Giác thú cấp Thiên Thần và Thiên lang, dựa vào manh mối của hai tộc để đổi hướng rồi bố trí vòng vây truy sát Hoang. U Vũ trách Vũ Luân hành động ngu xuẩn, tạm gác ý định giao chiến với Hoang và quyết định dẫn những thành viên Lục kiệt còn lại tới san bằng Đạo tràng Chí Tôn. Các học sinh dùng truyền tống trận báo tin cho gia tộc, mở đường cho sơ đại và chí tôn trẻ tuổi tới quan chiến. Cùng lúc đó, lực lượng Thiên Nhân tộc tại Hỏa châu cũng lùi lại theo manh mối mới, khiến hai hướng bão táp cùng dồn về Thiên Tiên châu."},{"chuong":759,"tieuDe":"Không Đề","tomTat":"Tin U Vũ sắp giao chiến khiến Học viện Thiên Tiên náo động, kéo theo tu sĩ và thiên kiêu từ Hỏa châu, Côn châu cùng nhiều đại giáo xa xôi đổ về Đạo trường Chí Tôn. Sơ đại Tiêu Đồ tộc, Liệt Thiên Ma điệp biến dị, sơ đại Kim Lang tộc, thánh nữ Kiếm cung, thiếu chủ Huyết hải cùng nhiều kỳ tài quen thuộc lần lượt xuất hiện để dò xét thực lực của U Vũ. U Vũ đứng trên phế tích sơn môn gọi đối thủ ra trận, còn Thạch Hạo chủ động chuyển chiến trường tới một đỉnh núi xa nhằm bảo vệ đạo tràng. U Vũ thi triển Ngũ sơn ấn, diễn hóa năm thần sơn giam cầm hư không, nhưng Thạch Hạo chỉ dùng một quyền đã đánh nổ toàn bộ. Vạn thú quyền tiếp tục gọi ra vô số hình ảnh hung thú và thần thú công kích, song vẫn không thể làm Thạch Hạo bị thương. U Vũ chuyển sang xé núi ném đối thủ rồi áp sát cận chiến, khiến hai bên trực tiếp va chạm quyền ấn. Ngay lần đối đầu đầu tiên đã có người đổ máu, nhưng chương kết thúc trước khi tiết lộ bên bị thương."},{"chuong":760,"tieuDe":"U Vũ Quyết Đấu Đại Sư Huynh","tomTat":"Sau lần đối chưởng đầu tiên, phần đông người quan chiến lầm tưởng máu trên tay Thạch Hạo là của hắn, nhưng Kim Lang chỉ rõ U Vũ mới là người bị thương. U Vũ dùng chính máu mình làm vật dẫn thi triển Huyết nê thủ, khiến cánh tay Thạch Hạo đỏ rực và đứng trước nguy cơ hóa thành bùn máu. Thạch Hạo vận chuyển bảo thuật, rung chuyển huyết nhục rồi ép sương máu cùng phù văn ra ngoài để phá giải bí thuật. Hai người tiếp tục chém giết hơn trăm hiệp, lần lượt triển khai Long hổ tranh bá bảo ấn, Kim Xà thối, Thiểm điện chưởng và Thiên Nhân khiếu. U Vũ dùng Thiên Ấn đánh nổ chiến mâu lôi điện, nhưng vết thương cũ trên ngón tay lại chảy máu, xác nhận Thạch Hạo đã làm hắn bị thương từ lần va chạm đầu tiên. Khi U Vũ tiếp tục hợp Thiên Ấn, Thạch Hạo gọi ra Thượng Thương kiếp quang hình thành từ Chí Tôn cốt, khiến chiến trường sôi trào trước đợt va chạm mới."},{"chuong":761,"tieuDe":"Ông Nội Mày Là Hoang","tomTat":"Thạch Hạo dùng Thượng Thương kiếp quang đối đầu Thiên ấn, khiến vết thương trên tay U Vũ tiếp tục nứt rộng nhưng cũng nhận ra đối thủ mạnh hơn dự liệu. U Vũ thi triển bảo thuật thiên phú, dựng nhà giam hư không và tạo ra những hiện tượng cướp đoạt ánh sáng, âm thanh, thân thể cùng nguyên thần của Thạch Hạo. Từ áp lực vô hình tác động lên Động thiên duy nhất, Thạch Hạo nhìn thấu bản chất không gian của bảo thuật và dùng Luân Hồi đánh nứt nhà giam, khiến U Vũ bị phản chấn thổ huyết. Khi U Vũ nhận ra thủ đoạn đặc trưng của Hoang, Thạch Hạo trực tiếp công khai thân phận, làm cuộc tỷ thí chuyển thành trận quyết chiến liên quan tới mối thù với Thiên Nhân tộc. Sau hơn bốn, năm trăm chiêu, Thạch Hạo triển khai hoàn toàn pháp môn Côn Bằng, hóa hàng ngàn chân vũ thành thiên tiễn xuyên qua Hư không đạo và Thiên ấn. U Vũ bị bắn thủng thân thể, nhà giam hư không tan vỡ và cả hai trở lại trước đám đông, trong đó Thạch Hạo bước ra với phong thái áp đảo."},{"chuong":762,"tieuDe":"Thần Thoại Thiên Mệnh","tomTat":"Chân vũ Côn Bằng của Thạch Hạo xuyên vào thân thể U Vũ, khiến cao thủ trẻ tuổi số một Thiên Nhân tộc trọng thương và buộc các cường giả trong tộc bí mật tính chuyện can thiệp. Vân Hi bị thúc ép sử dụng thánh vật hình hoa sen có thể giết Chân Thần nhưng chần chừ, trong khi Thanh Y tập hợp Phượng Vũ cùng các trưởng lão Thư viện Thiên Tiên và hiển lộ ngọn lửa xanh để ngăn cản. U Vũ nhận ra đối thủ là Hoang đến từ hạ giới, song ngăn tộc nhân trực tiếp giết Thạch Hạo vì muốn tự mình hoàn thành trận chiến. Hắn dùng Hư không đạo kéo giãn khoảng cách rồi được Thiên Mệnh thạch trong cơ thể chữa lành huyết nhục, nối lại xương cốt và ép toàn bộ chân vũ Côn Bằng ra ngoài. Kỳ thạch tiếp tục giúp U Vũ hiển hóa Thiên chi dực, Thiên chi giác cùng thần giáp trời ban, đưa hắn vào trạng thái hiếm có mang tên Thần thoại Thiên Mệnh. Trước đối thủ đã phục hồi và tăng vọt năng lực, Thạch Hạo vẫn đứng yên như núi rồi tung quyền kim quang nghênh chiến."},{"chuong":763,"tieuDe":"Hoang Vô Địch","tomTat":"Thạch Hạo trực diện giao chiến với U Vũ, người đã dung hợp Thiên Mệnh thạch và tiến hóa mạnh mẽ, nhưng vẫn dần chiếm ưu thế trước sự kinh hãi của những người quan chiến. U Vũ kéo đối thủ vào nhà giam hư không, liên tiếp dùng Thiên chi giác, Thiên chi dực, thần giáp trời ban và Thiên ấn, còn Thạch Hạo vận chuyển Nguyên thủy chân giải, mở Động thiên duy nhất và diễn hóa thần hi thành lò luyện cùng nhiều loại binh khí để chống trả. Sau khoảng năm trăm hiệp, Thạch Hạo đưa pháp môn Côn Bằng tới cực điểm, cắt đứt Thiên chi dực, phá thần giáp và hóa giải vụ tự nổ giáp trụ. U Vũ bị đánh trọng thương, còn bí bảo mang uy thế Thiên Thần của hắn cũng bị cục bùn nhão làm mất hiệu lực. Bất chấp lực lượng Thiên Nhân tộc xông vào cứu viện, Thạch Hạo dùng đao Thiểm điện chém U Vũ thành hai nửa rồi cuốn Thiên Mệnh thạch về tay mình. U Vũ bị coi như đã phế, đồng thời tiếng gọi của hắn làm lộ thân phận Hoang của Thạch Hạo trước tu sĩ các giáo, khiến cả vùng núi chấn động."},{"chuong":764,"tieuDe":"Muôn Người Chú Ý","tomTat":"Thân phận Hoang của Thạch Hạo bị công khai, khiến quần hùng chấn động khi những chiến tích của hắn trước các sơ đại cùng thành tích vượt thang trời được nhắc lại. U Vũ bị chém mất nửa thân dưới và mất Thiên Mệnh thạch, buộc một thần linh Thiên Nhân tộc phải khẩn cấp chữa trị, còn uy danh của cả bộ tộc chịu đả kích nặng nề. Vân Hi nhận ra Hoang chính là người từng hộ tống mình từ hạ giới, trong khi Thanh Y bình thản vì đã phần nào đoán ra thân phận của hắn. Thạch Hạo đứng giữa vùng núi với Thiên Mệnh thạch trong tay, trở thành tâm điểm khi kỳ thạch phát hào quang nhiều màu và sóng năng lượng dữ dội. Trước cáo buộc hắn trà trộn vào Thiên Chi Thành, mưu đoạt Phi Tiên thạch và phá thần quáng, Thạch Hạo công khai tố Thiên Nhân tộc vong ân, từng giam mình để chiếm bảo thuật. Hắn tiếp tục chế giễu cao thủ và chí tôn trẻ tuổi của đối phương, khiến Thiên Nhân tộc khó thể phản bác sau thất bại của U Vũ. Cuối chương, một cao tầng Thiên Nhân tộc ép Vân Hi dùng pháp khí Thiên Thần giết Thạch Hạo để cứu vãn thể diện, còn hai người chỉ lặng nhìn nhau khi nàng chưa kịp lựa chọn."},{"chuong":765,"tieuDe":"Hóa Trang Diễn Kịch","tomTat":"Bị các thần linh Thiên Nhân tộc ép tiếp cận Thạch Hạo để ám sát, Vân Hi giả vờ dùng pháp khí Thiên Thần tấn công rồi lợi dụng hư không hỗn loạn để bí mật truyền âm. Nàng xin lỗi về chuyện tại Thiên Chi Thành và muốn trao pháp khí phá không cho hắn đào thoát, nhưng Thạch Hạo khẳng định không trách nàng, trả lại pháp khí và quyết định ở lại nghênh chiến. Khi kế hoạch của Vân Hi bại lộ, Thiên Nhân tộc điều mười hai cao thủ Thần Hỏa cảnh và năm Chân Thần công khai vây giết. Thạch Hạo dùng nước Thiên hà, tia chớp, bùn nguyền rủa và chiếc bình gần cấp Thiên Thần phá thế bao vây, đồng thời dựa vào khả năng miễn dịch pháp lực để áp sát và giết bốn cao thủ Thần Hỏa cảnh. Hắn tiếp tục kích nổ thần phù đỏ lấy từ Vũ Luân, giết một Chân Thần, trọng thương người thứ hai rồi truy kích chém đầu và đánh tan nguyên thần của người này. Trước khi trạng thái miễn dịch pháp lực kết thúc, Thạch Hạo lui về sơn môn Đạo tràng Chí Tôn. Một Thiên Thần lão tổ của Thiên Nhân tộc đánh bàn tay khổng lồ xuống sơn môn, nhưng cường giả chưa rõ danh tính trong đạo tràng công khai nhận Thạch Hạo là đệ tử, phá tan công kích và hất vị Thiên Thần xuống dãy núi."},{"chuong":766,"tieuDe":"Đạo Chủ","tomTat":"Bàn tay vàng từ sơn môn Đạo tràng Chí Tôn đánh Thiên Thần Mạc La bay xuyên dãy núi, phá hủy cánh tay phải của hắn, trong khi Thạch Hạo vẫn bình tĩnh đứng trước phế tích. Mạc La tái tạo cánh tay rồi chất vấn Tề Đạo Lâm, nhưng Đạo chủ công khai nhận Thạch Hạo làm đệ tử và tuyên bố bảo vệ môn đồ. Quá khứ của Tề Đạo Lâm cũng được hé lộ: lão từng là truyền nhân duy nhất của một đạo thống cổ bị Tiên điện cùng nhiều phía vây công, từ đó đi trộm cướp bí pháp của các đại giáo để mạnh lên và trả đũa. Khi biết U Vũ đã mất Thiên Mệnh thạch vào tay Thạch Hạo, Mạc La đòi thu hồi chí bảo nhưng bị tiếng quát hóa thành sóng vàng của Tề Đạo Lâm đánh gãy xương toàn thân, trọng thương không thể đứng dậy. Người Hộ đạo cùng một Thiên Thần trung niên của Thiên Nhân tộc sau đó đi theo đại lộ kim quang tới sơn môn và chất vấn Tề Đạo Lâm về khả năng khai chiến. Tề Đạo Lâm thẳng thừng nhận lời thách thức, khiến phía Thiên Nhân tộc không dám đáp vì lo tộc chiến ảnh hưởng vận mệnh bộ tộc. Cuối cùng, lão cho phép cường giả Thần Hỏa cảnh tham gia tranh bá thế hệ trẻ nhưng cảnh cáo rằng bất kỳ Thiên Thần nào dám ra tay đều sẽ bị giết."},{"chuong":767,"tieuDe":"Thông Báo Thiên Hạ","tomTat":"Trước yêu cầu giao Thạch Hạo cho Thiên Nhân tộc, Tề Đạo Lâm công bố Hoang là truyền nhân duy nhất của Đạo tràng Chí Tôn, khiến thân phận sư môn của hắn được xác lập trước thiên hạ. Trong lúc Tề Đạo Lâm và người Hộ đạo giao chiến tại vực ngoại, Mạc La bí mật dùng Chủng ma thuật nhằm phá hoại đạo tâm Thạch Hạo, nhưng thần giác của hắn cùng cốt văn Nguyên thủy chân giải lập tức phát hiện nguy hiểm. Tề Đạo Lâm từ xa ngưng tụ bàn tay cốt văn, phá hủy pháp khí và đánh nát thân thể Mạc La, chỉ giữ lại một tia nguyên thần để sau này Thạch Hạo tự tay giải quyết. Người Hộ đạo dùng Thần dịch bất lão khôi phục hình dáng thanh niên và thi triển thần thông mạnh nhất, song vẫn bị Bát Cửu Thiên Công đánh trọng thương, phải dùng hai chiếc sừng thế mạng rồi rút lui. Chiến thắng này khiến các cường giả chứng kiến thừa nhận Tề Đạo Lâm đã đủ sức đứng ngang hàng với bá chủ cấp Giáo chủ. Sau trận chiến, lão cho phép Tôn Giả và tu sĩ Thần Hỏa cảnh khiêu chiến hoặc truy sát Thạch Hạo, nhưng cảnh cáo sẽ hủy đạo vận và giết môn đồ của bất kỳ thế lực nào để Thiên Thần lấy lớn hiếp nhỏ."},{"chuong":768,"tieuDe":"Thiên Hạ Lay Chuyển","tomTat":"Sau trận chiến, Thiên Nhân tộc chịu tổn thất nặng nề và buộc phải rút lui trước uy thế của Tề Đạo Lâm, còn việc Thạch Hạo trở thành truyền nhân Đạo tràng Chí Tôn khiến những kẻ muốn đối phó hắn phải dè chừng. Thạch Hạo lo Vân Hi bị bộ tộc trách phạt vì đã giúp mình, nhưng nàng vẫn quyết định trở lại Thiên Chi Thành vì không thể bỏ tổ phụ, thân nhân và Thiên Nhân tộc. Tin Hoang đánh bại nhiều kỳ tài và khiến Thiên Nhân tộc đại bại nhanh chóng truyền khắp hàng chục đến hàng trăm châu. Trong Tiên điện bằng đồng, chủ thân của truyền nhân Tiên điện triệu hồi thứ thân để hợp nhất, chuẩn bị đạt trạng thái mạnh nhất trước khi tiến vào Tiên cổ. Cùng lúc đó, chàng trai tóc tím có mắt dọc xuất quan sau hai mươi năm ẩn tu và công bố đã luyện Phần Thiên công tới tầng thứ chín. Một thiếu nữ tóc vàng cũng thức tỉnh trong thủy phủ dưới hồ vàng, tỏa ra khí tức đáng sợ dù chưa nhóm Thần hỏa. Khắp nhiều cổ châu, các kỳ tài từng được đạo thống che giấu lần lượt xuất thế, báo hiệu đại chiến thiên tài ba ngàn châu sắp mở màn."},{"chuong":769,"tieuDe":"Tận Thế Rực Rỡ","tomTat":"Thạch Hạo đòi Tề Đạo Lâm ban bảo vật trấn giáo, nhưng vị đạo chủ chỉ khuyên hắn tự mình tranh đoạt mọi thứ trong thiên hạ. Từ chuyện hai đệ tử cũ của Đạo tràng Chí Tôn từng bị đánh bại, Tề Đạo Lâm hé lộ một cường giả cổ đại từng đứng đầu đại quyết chiến thiên tài ba ngàn châu có thể tái xuất. Lão còn cho biết nhiều kỳ tài cổ đại tưởng đã chết thực ra đang ẩn trong cấm địa, khiến cuộc tranh phong sắp tới nguy hiểm hơn dự kiến. Hoa Chân tiên chỉ còn nở một lần, sau đó ba ngàn con đường tiến vào Tiên cổ sẽ đóng vĩnh viễn. Những nhân vật cấm kỵ cũng không thể suy diễn tương lai, làm dấy lên dự báo rằng kỷ nguyên hiện tại có thể đi đến hồi kết. Cuối cùng, Thạch Hạo tiết lộ mình từng thấy Tam thế đồng quan do chín con rồng kéo, khiến Tề Đạo Lâm kích động vì tin tức liên quan đến sư phụ. Hai thầy trò cùng lên đường tới bình nguyên màu máu để mở cổ quan."},{"chuong":770,"tieuDe":"Mở Ra Tam Thế Đồng Quan","tomTat":"Thạch Hạo dẫn Tề Đạo Lâm xuống hang ngầm sâu dưới thảo nguyên Hỏa châu, nơi cất giấu Tam thế đồng quan cùng chín bộ long cốt. Trước quan tài, Tề Đạo Lâm lần đầu xác nhận mình xuất thân từ Cung điện Chí Tôn và kể rằng sư phụ từng truy tìm vật này, khiến đạo thống suy yếu. Lão vận chuyển Bát Cửu Thiên Công tới cực hạn để cưỡng ép mở nắp nhưng liên tục bị sức phản kích đánh văng và làm trọng thương. Đến lần thử thứ sáu, Tề Đạo Lâm tiếp nhận được một đoạn thần thức không đầy đủ của sư phụ, trong đó lưu lại lời cảnh báo đầy sợ hãi rằng những tồn tại bí ẩn sắp đến. Trong lần thử cuối, chín bộ long cốt và quan tài đồng đồng loạt bùng sáng, còn nắp quan tài bất ngờ tự mở tới một nửa. Giữa mưa ánh sáng thánh khiết, một bóng người bí ẩn lao ra và đứng giữa không trung với khí tượng như vượt trên dòng thời gian."},{"chuong":771,"tieuDe":"Mười Vị Tiên","tomTat":"Tam thế đồng quan lần lượt phóng ra một cổ tăng áo trắng, một đạo nhân bị nghi là Thanh Vi Thiên chủ cùng tám bóng người khác, hợp thành đúng mười người mang thần vận cái thế. Thạch Hạo và Tề Đạo Lâm gắng sức chống lại áp lực tự nhiên từ họ, nhưng các bóng sáng không hề để ý đến hai thầy trò mà cùng hướng về một phương. Khi rời khỏi lòng đất, họ vỡ thành mười luồng sáng và bay thẳng tới khu vực không người, khiến Tề Đạo Lâm lo rằng việc mở quan tài đã thúc đẩy một tiến trình chưa rõ tốt xấu. Trở lại bên quan tài, Thạch Hạo dùng ngôn ngữ cúng tế Tiên cổ thử kết nối với đốm lửa thần bí nhưng không thành công. Tề Đạo Lâm chuyển sang vận dụng cốt văn để thu lấy nó, lập tức bị đốm lửa bùng phát sức nóng dữ dội và truy đuổi khỏi lòng đất. Khi chỉ còn ở bên Thạch Hạo, đốm lửa trở nên nhu hòa rồi lần lượt biến thành cây nhỏ giống Liễu Thần, tia chớp gợi pháp môn Lôi Đế và hình chim hóa cá của Côn Bằng. Thạch Hạo nhận ra nó có thể cảm ứng những pháp môn mình từng học, nhưng chưa biết nó đang mô phỏng để học hỏi hay muốn tạo liên hệ với hắn."},{"chuong":772,"tieuDe":"Lửa Chính Là Gương","tomTat":"Đốm lửa thần bí diễn hóa hình thái giống Liễu Thần và ý cảnh của bảo thuật Lôi Đế, giúp Thạch Hạo nhận ra những thiếu hụt trong pháp và Đạo của mình. Khi Tề Đạo Lâm trở lại bằng Bát Cửu Thiên Công, đốm lửa bùng phát uy thế kinh người nhưng không làm Thạch Hạo bị thương, sau đó biến mất đến mức hai thầy trò không thể tìm ra. Chín bộ xương rồng kéo Tam Thế Đồng Quan xé hư không rời đi, còn Tề Đạo Lâm từ bỏ truy đuổi vì sư tôn từng mất mạng sau một lần làm như vậy. Tề Đạo Lâm đề nghị đoạt Đại Xích Thiên hỏa cho đệ tử, nhưng Thạch Hạo từ chối vì không muốn đi theo con đường của người khác và không muốn sư phụ mạo hiểm. Trở về sơn môn, Thạch Hạo tụ hội với Khổng Cầu Kỷ, Tào Vũ Sinh và Thái Âm Ngọc Thỏ, đồng thời biết có những đối thủ mang đại sát khí hoặc đã vào Thần Hỏa cảnh có thể tới khiêu chiến. Tào Vũ Sinh và Khổng Cầu Kỷ tiết lộ truyền nhân Tiên điện cùng Nguyệt Thiền đang chú ý tới Thanh Y tại Thư viện Thiên Tiên. Nhận ra Thanh Y có thể bị chặn trong thư viện, Thạch Hạo lập tức dẫn mọi người lên đường."},{"chuong":773,"tieuDe":"Tiên Điện Vs Đạo Trường Chí Tôn","tomTat":"Sau biến cố do Hoang gây ra tại Hỏa châu, nhiều cao thủ và thiên kiêu tập trung ở Thư viện Thiên Tiên, trong khi Bí cốc tiết lộ truyền nhân Tiên điện đi lại bên ngoài lâu nay chỉ là thứ thân. Chủ thân và thứ thân của hắn đang chuẩn bị dung hợp trước đại quyết chiến thiên tài ba ngàn châu, khiến các đại giáo đặc biệt cảnh giác. Truyền nhân Tiên điện cùng Nguyệt Thiền tới nơi tu đạo của Thanh Y, yêu cầu nàng trở về dung hợp với chủ thân, nhưng Thanh Y khẳng định mình là một cá thể độc lập và kiên quyết từ chối. Ông lão của thư viện cùng Phượng Vũ đứng ra bảo vệ nàng, không cho người ngoài cưỡng ép đệ tử rời đi. Truyền nhân Tiên điện còn muốn quan sát quá trình hai thân Nguyệt Thiền hợp nhất để tích lũy kinh nghiệm cho chính mình, nhưng sau khi bị bác bỏ, hắn chỉ có thể tuyên bố sẽ quay lại. Đúng lúc ấy, Thạch Hạo dùng cánh sét lao tới, công khai ngăn cản và đối đầu với hắn. Ân oán lâu đời giữa Tiên điện và tiền thân của Đạo tràng Chí tôn tiếp tục bùng phát, còn Thạch Hạo ôm Thanh Y trước đám đông và tuyên bố sẽ chém truyền nhân Tiên điện thêm một lần nếu đối phương không phục."},{"chuong":774,"tieuDe":"Hai Cường Giả Quyết Đấu","tomTat":"Truyền nhân Tiên điện dùng kiếm khí uy hiếp Thạch Hạo và phủ nhận truyền thừa của Cung điện Chí tôn, nhưng một lão Thiên Thần của Thư viện Thiên Tiên xuất hiện ngăn hai người giao chiến tại nơi tĩnh tu của nữ đệ tử. Thạch Hạo cố ý thân mật với Thanh Y, khiến chủ thân Nguyệt Thiền cảm nhận qua mối liên hệ giữa hai thân và tức giận quát hắn, còn hắn tiếp tục khiêu khích cả nàng lẫn truyền nhân Tiên điện. Hai đối thủ sau đó chuyển tới sân diễn võ của thư viện để phân thắng bại sống còn, thu hút học sinh, khách các tộc và đông đảo tu sĩ đến quan chiến. Thái Âm Ngọc Thỏ công khai đứng về phía Hoang, liên tục nhắc việc truyền nhân Tiên điện từng bị hắn chém khiến phe ủng hộ đối phương không thể phản bác. Khi trận đấu bắt đầu, truyền nhân Tiên điện thi triển Hoàng vũ kiếm dực, còn Thạch Hạo dùng kiếm ý của cọng cỏ rồi giấu cánh Côn Bằng trong đôi cánh tia chớp để đối đầu. Đòn phản kích của Thạch Hạo khiến cổ đối phương chảy máu và suýt bị cắt rời đầu, buộc truyền nhân Tiên điện thừa nhận pháp lực của Hoang đã đuổi kịp mình và cân nhắc dung hợp với chủ thân. Thạch Hạo kết thúc lần giao phong đầu tiên bằng lời tuyên bố rằng nếu đối thủ chỉ có bấy nhiêu năng lực thì hắn sẽ tiễn đối phương chầu trời."},{"chuong":775,"tieuDe":"Một Mạch Chí Tôn","tomTat":"Truyền nhân Tiên điện miệt thị đạo thống Chí Tôn, khiến Thạch Hạo lập tức giao chiến với thứ thân của hắn trên võ đài Thư viện Thiên Tiên. Thạch Hạo dùng Bảo thuật Lôi Đế đối đầu Hoàng vũ kiếm dực, xuyên thủng vai đối thủ, nhưng tạm thời bị áp chế khi truyền nhân Tiên điện kích hoạt Tiên chủng không trọn vẹn và thi triển Nhân Tiên ấn. Khi sức mạnh từ giọt chân huyết suy giảm, Thạch Hạo phản công bằng lôi đình, phá pháp ấn, làm nứt xương trán và suýt dùng kiếm ý chém nguyên thần đối phương. Lão bộc Tiên điện bí mật truyền pháp lực cho chủ nhân rồi công khai đưa hắn khỏi đòn kết liễu, sau đó dùng uy thế chèn ép Thạch Hạo và đe dọa Đạo tràng Chí Tôn. Tề Đạo Lâm cách không bắt giữ cường giả gần đạt Thiên Thần cảnh, bác bỏ lời biện hộ và bóp nát lão bộc. Ông kết thúc sự việc bằng lời cảnh cáo Tiên điện không được can thiệp vào một mạch Chí Tôn."},{"chuong":776,"tieuDe":"Chiến Lợi Phẩm","tomTat":"Tề Đạo Lâm không cần chân thân giáng lâm mà vẫn dùng một bàn tay vàng xuyên qua hư không bóp chết lão bộc Tiên điện, sau đó bắt giữ truyền nhân của thế lực này. Theo lời nhắc của viện trưởng Thư viện Thiên Tiên và vì an nguy lâu dài của Thạch Hạo, lão không giết đối phương mà yêu cầu hắn trở về dung hợp chủ thân rồi tái chiến. Tề Đạo Lâm tịch thu các bảo vật, trả lại Chiến giáp Tiên Vũ cùng cung điện đồng phỏng chế, nhưng trao Chiến kích Hư không và toàn bộ bảo dược cho Thạch Hạo làm chiến lợi phẩm. Chủ thân Nguyệt Thiền dùng Phá vực phù trốn đi, còn Thanh Y ngăn Thạch Hạo truy kích vì chưa sẵn sàng kết thúc quan hệ với chủ thân và quyết định tới một đạo thổ thần bí tĩnh tu. Khổng Cầu Kỷ, Thái Âm Ngọc Thỏ và những người khác lần lượt chia tay, trong đó Ngọc Thỏ hẹn kết minh với Thạch Hạo tại đại chiến thiên tài thượng giới. Trở lại Đạo tràng Chí Tôn, Thạch Hạo biết Tam thế đồng quan đã phóng ra mười luồng tiên quang và Tề Đạo Lâm sẽ tới vùng trọng yếu của Hỏa châu rồi tiến vào khu vực không người điều tra. Trước khi đi, Tề Đạo Lâm yêu cầu đệ tử phải giết truyền nhân Tiên điện sau khi hắn dung hợp chủ thân, còn Thạch Hạo chuẩn bị tìm Đả Thần Thạch và Hoàng điệp rồi tham dự đại chiến."},{"chuong":777,"tieuDe":"Tiên Quáng","tomTat":"Tề Đạo Lâm cho Thạch Hạo biết người hắn từng giao chiến chỉ là thứ thân của truyền nhân Tiên điện, còn chủ thân mạnh hơn và việc dung hợp hai thân sẽ khiến chiến lực tăng vọt. Lão giải thích cổ pháp này bắt nguồn từ một sinh linh bất diệt, có khả năng giúp một thân tái sinh khi thân kia còn sống và tiếp tục mạnh lên qua niết bàn sinh tử. Trước khi rời đạo tràng, Tề Đạo Lâm cảnh báo Thạch Hạo đề phòng Thiên Nhân tộc và người Hộ đạo đang gần cạn sinh mệnh, đồng thời kể về các tạo hóa trong Tiên cổ cùng sự mất tích của Tam thạch Thiên quân. Hai thầy trò sau đó tiến sâu vào sa mạc Hỏa châu để chờ tiên quáng mà Tề Đạo Lâm đã theo dõi từ lâu. Sau sáu ngày, mặt cát nứt ra và một ngọn núi phủ sương mù hỗn độn trồi lên, để lộ động cổ phát ra khí lành cùng âm hưởng đại đạo. Khi tiến vào bên trong, Thạch Hạo nhận ra quáng động là công trình nhân tạo, còn Tề Đạo Lâm phát hiện nhiều dấu binh khí chứa thần vận của các cao thủ cái thế. Cuối cùng, lão suy đoán toàn bộ động phủ được tạo từ một mảnh chí bảo Hỗn Nguyên thạch từng bị phá nát trong đại chiến."},{"chuong":778,"tieuDe":"Bảo Điện Của Tiên","tomTat":"Tề Đạo Lâm dẫn Thạch Hạo tiến sâu vào Tiên quáng, nơi những dấu tích chiến đấu và đồ án cổ vẫn mang áp lực đại đạo mạnh mẽ. Thạch Hạo thu một khối Hỗn Nguyên thạch nứt vỡ, sau đó lĩnh hội các hình khắc trong bảo điện và vô thức tạo ra quầng sáng phù văn có thể phản chiếu đồ án cùng chân nghĩa đại đạo. Hai thầy trò phát hiện phần lớn tiên liệu từng được thờ trong điện chỉ còn huyễn ảnh, nhưng Tề Đạo Lâm vẫn tìm thấy một khối vật liệu đen đang bị phong ấn. Ông thiêu đốt máu, vận chuyển Bát Cửu Thiên Công để phá phong ấn, đoạt tiên liệu rồi đưa Thạch Hạo rời khỏi cổ điện. Khi ngọn núi chìm xuống đất, một khối tiên kim bảy màu đã thông linh và hóa thành hình cô gái xuất hiện, nhưng hai người không quay lại thu lấy. Trước lúc chia tay, Tề Đạo Lâm chỉ dẫn Thạch Hạo tiếp tục nghiên cứu dị tượng đại đạo, đồng thời tuyên bố sẽ khôi phục truyền thừa Chí Tôn sau khi biết tin về Cung điện Chí tôn. Thạch Hạo sau đó rời Hỏa châu và Thiên Tiên châu để tiếp tục hành trình."},{"chuong":779,"tieuDe":"Gặp Lại","tomTat":"Trước khi tham gia đại chiến ba ngàn châu, Thạch Hạo vượt qua nhiều châu để tới vùng núi lửa Ma châu thăm Thập Ngũ gia. Ông nội hắn đã gần hóa giải hết âm khí từ chân huyết Ma tôn, tóc dần chuyển đen và cánh tay bị đứt cũng mọc lại. Sau khi nghe cháu kể về biến cố với Thiên Nhân tộc, Thập Ngũ gia giao Vạn Linh đồ cho hắn, nhận nửa Thiên Mệnh thạch và chỉ mong hắn sống sót trở về. Thạch Hạo còn truyền ngôn ngữ tế tự cổ xưa cho ông thử tìm cơ duyên từ cổ hỏa dưới quần thể núi lửa. Tới Ngũ Hành châu, hắn hội ngộ Đả Thần Thạch và Hoàng điệp, biết Ngân hoàng đã tỉnh lại rồi truy đánh Đả Thần Thạch để trả đũa. Đả Thần Thạch nuốt nửa Thiên Mệnh thạch và nhận thêm hơn mười khối Hỗn Nguyên thạch để tiến hóa. Sau đó Thạch Hạo trở lại đảo Ác Ma, thu lượng lớn nước Thiên hà cùng đất Mộ tiên làm hậu chiêu. Cuối cùng, hắn chọn Tội châu làm điểm đến tiếp theo, vừa muốn tìm Hỏa Linh Nhi vừa quyết tâm từ nơi tụ tập sinh linh hạ giới tiến vào đại chiến và đánh bại các thiên tài đương thời."},{"chuong":780,"tieuDe":"Đời Sau Tội Huyết","tomTat":"Sau nhiều ngày vượt qua hàng trăm châu bằng các truyền tống trận cực lớn, Thạch Hạo tới Tang thành thuộc Tội châu và bắt đầu dò hỏi tình hình. Hắn biết vùng đất linh khí mỏng manh này bị xem là nơi lưu đày hậu duệ tù nhân cùng đại hung từ hạ giới, còn nguồn gốc lời nguyền Tội huyết được giải thích bằng nhiều lời đồn mâu thuẫn. Đông đảo Tôn giả ngoại châu cũng kéo tới đây nhằm giành tư cách tiến vào Tiên cổ, nơi được truyền tụng có vô số linh dược, truyền thừa và thần vật. Trước thái độ khinh miệt hậu duệ Tội huyết của các tu sĩ ngoại lai, Thạch Hạo phẫn nộ và không chấp nhận việc gán tội lỗi của tổ tiên cho đời sau. Khi tìm hiểu tung tích Thạch tộc, hắn biết Thạch Quốc cổ xưa đã bị một bàn tay lớn từ trời san bằng sau thời kỳ quật khởi. Thạch Hạo tới phế tích thủ phủ, tìm thấy những hậu duệ Thạch Quốc đã trở thành người phàm và được một ông lão hé lộ rằng tổ tiên Thạch tộc gặp họa vì từng biết một phần chân tướng bị che giấu."},{"chuong":781,"tieuDe":"Tội Lỗi Cùng Huy Hoàng","tomTat":"Tại một trại đá nghèo khó ở Tội châu, Thạch Hạo biết Thạch tộc và Hỏa tộc nằm trong ba mươi tộc bị quy là hậu duệ mang tội huyết. Hắn để lại bảo vật cho các di dân rồi tới phế đô Thạch tộc, dùng tảng đá cổ kiểm tra huyết mạch và khiến ký hiệu trên xương trán hiển hóa thành chữ “Tội” hoàn chỉnh soi sáng trời xanh. Trong lúc cộng hưởng, hắn nghe tiếng nói khẳng định tổ tiên tội huyết từng lập công cái thế và vẫn đang huyết chiến, trấn thủ biên hoang. Dị tượng khiến nhiều đạo thống cùng các tồn tại cổ xưa chấn động, nhưng Thạch Hạo kịp dùng chiến kích hư không rời đi trước khi các cao thủ tới truy xét. Sau đó hắn cảm ngộ đại Đạo, tiến sát Tôn giả đại viên mãn nhưng quyết định chờ đoạt tạo hóa thiên địa để gột rửa bản thân trước khi đột phá, đồng thời chọn Hỏa châu làm điểm đến tiếp theo để tìm Hỏa Linh Nhi. Tại Thiên châu, cao tầng Thiên Nhân tộc muốn bí mật bắt sống hắn và độc chiếm pháp môn Côn Bằng; người Hộ đạo bất chấp lời can ngăn của Mạc La để thi triển bói toán. Phép bói thất bại và phản phệ nghiêm trọng, chỉ để lộ một tương lai hỗn độn, một quá khứ hư vô cùng nhận định rằng Thạch Hạo dường như không thuộc về toàn bộ lịch sử cổ xưa này."},{"chuong":782,"tieuDe":"Hỏa Thành","tomTat":"Tại Thiên Chi Thành, người Hộ đạo hấp hối vì bói toán Thạch Hạo nhưng bị sức mạnh khó lường cắn trả, khiến Mạc La, Thích Thác và các Thiên Thần phải tìm cách giữ mạng cho ông trong lúc Lão Thiên Nhân đã tiến vào vùng cấm thực hiện Minh ước Thái cổ. Không biết biến cố này, Thạch Hạo tới Hỏa quốc tại Tội châu để tìm Hỏa Hoàng và Hỏa Linh Nhi nhưng không ai trong hoàng đô biết tên nàng. Hắn quyết định lưu lại Hỏa thành và biết nhiều thiên tài, sơ đại từ các châu đang tụ tập để chờ một cường giả trẻ tuổi thần bí. Nghe tin Lục công chúa tổ chức thịnh hội ngoài hoàng đô, Thạch Hạo tới trang viên dù không có thiệp mời và vẫn được cho vào. Trong trang viên, hắn phát hiện một vườn thuốc được đại trận bảo vệ, bên trong có hơn mười cây linh dược sống sót sau đợt chết hàng loạt rồi biến dị thành Thánh dược. Khi biết những cây thuốc này được mang từ hạ giới lên, Thạch Hạo nhận ra mình đã tìm được manh mối có thể dẫn tới Hỏa Hoàng và Hỏa Linh Nhi."},{"chuong":783,"tieuDe":"Nhân Kiệt Vô Thượng","tomTat":"Trong vườn thuốc đất năm màu, Thạch Hạo biết hơn mười linh dược từ hạ giới đã vượt qua áp lực đạo tắc thượng giới và lột xác thành Thánh dược. Qua lời người chăm sóc, hắn tin hai cha con mang số thuốc này tới chính là Hỏa Hoàng và Hỏa Linh Nhi, đồng thời đau xót vì bản thân từng ăn hết mấy trăm cây linh dược có tiềm năng tương tự. Giữa lúc các tu sĩ bàn luận việc Hoang đánh bại thứ thân của truyền nhân Tiên điện, Thiên Dao công khai ủng hộ Hoang và báo rằng Trường Cung Diễn sắp tái xuất. Trường Cung Diễn xuất hiện trước mộ người tri kỷ đã mất, để lộ uy thế khiến nhiều Tôn Giả không thể tới gần, cùng quá khứ bốn lần đứng đầu đại chiến thiên tài ba ngàn châu và nhiều lần tìm hồ máu Phượng Hoàng để cứu người yêu. Cô Kiếm Vân của Kiếm Cốc lập tức thách đấu chàng, khiến hư không nứt vỡ trước khi cả hai chuyển vào khe nứt để tiếp tục giao chiến. Sau đó, cô gái áo vàng của Kiếm Cốc dùng tranh quý dò tìm hậu duệ tội huyết, vô tình kích phát ký hiệu trên trán Thạch Hạo thành luồng sáng xuyên trời. Nàng kinh hãi nhận ra hắn có liên hệ với chữ tội từng in dấu trên vòm trời và chiếu rọi chư thiên."},{"chuong":784,"tieuDe":"Tội Huyết Sát Phạt","tomTat":"Hoa văn trên trán Thạch Hạo hóa thành chữ “tội” rực sáng giữa hư không, khiến tu sĩ các châu kinh hãi trước mức độ nồng đậm của tội huyết. Hắn chất vấn cô gái áo vàng của Kiếm Cốc về căn cứ kết tội tổ tiên mình, nhưng nàng chỉ có thể viện dẫn phán xét chung của các đạo thống và kết quả từ cốt kính. Nhớ lại những điều từng biết tại di tích Thạch quốc, Thạch Hạo khẳng định tổ tiên đã đổ máu chiến đấu ở tuyến đầu và không chấp nhận sự khinh miệt dành cho họ. Khi cô gái dựa vào uy danh Kiếm Cốc cùng Cô Kiếm Vân để đe dọa, hắn ra tay đánh nàng thổ huyết và phát hiện chữ “tội” có thể gia trì sức mạnh. Trong trận giao chiến, Thạch Hạo đánh gãy pháp kiếm thần linh, áp đảo mọi bảo cụ rồi vận dụng pháp môn diễn hóa thần hi để lấy thân hóa kiếm, chém đối thủ thành hai nửa. Thiên Dao công khai vỗ tay tán thưởng, còn các tu sĩ nhận định cái chết của truyền nhân Kiếm Cốc sẽ gây nên một trận phong ba lớn vì Cô Kiếm Vân có thể vẫn đang ở gần."},{"chuong":785,"tieuDe":"Hàng Loạt Vương Giả Xuất Hiện","tomTat":"Sau khi giết đệ tử Kiếm Cốc, Thạch Hạo để chữ Tội chiếu rọi trời cao và công khai khẳng định dấu ấn ấy tượng trưng cho vinh quang cùng công lao của tổ tiên, đồng thời thách thức mọi kẻ muốn phán xét mình. Hắn dùng chiến kích hư không rời Hỏa thành trước khi Thiên Thần giáng lâm, còn dị tượng tội huyết lần thứ hai khiến các đại giáo quyết tâm truy tìm người mang dấu ấn. Cô Kiếm Vân và Trường Cung Diễn đều tái xuất sau trận chiến chưa rõ thắng bại; một người khiến vạn vật cộng hưởng khi luyện kiếm, người kia hòa vào thiên địa đến mức các Thần linh có ác ý không thể giữ được tung tích. Tử Viêm Phi kéo đứt xích thần, tuyên bố Đại Phần Thiên Công đã đạt cực hạn rồi vượt nhiều châu, liên tiếp đánh bại và giết các cường giả trẻ tuổi trước khi tới Tội châu công khai khiêu chiến. Lục Quan Vương Ninh Xuyên cũng hiện thân, coi người mang chữ Tội là con mồi và tuyên bố sẽ chém đối phương để bảo vệ đại đạo. Trong khi chưa biết mình bị săn tìm, Thạch Hạo đã vào một dãy núi nguyên thủy, chờ mưa giông để vận dụng Bảo thuật Lôi Đế dẫn thiên kiếp rèn thân thể cùng nguyên thần, chuẩn bị xung kích Tôn Giả cảnh đại viên mãn."},{"chuong":786,"tieuDe":"Thiên Kiếp","tomTat":"Thạch Hạo điều chỉnh tinh khí thần tới trạng thái cao nhất rồi bay lên tầng mây, vừa tìm Lôi Kiếp dịch vừa muốn dùng lôi đình tự nhiên rèn luyện thân thể. Những tia sét đầu tiên đã khiến hắn da tróc thịt bong, nhưng áp lực từ các quái thai thời cổ và truyền nhân của những đạo thống lớn khiến hắn quyết định không rút lui. Trong tầng mây, hắn vận chuyển cốt văn cùng Bảo thuật Lôi Đế, dẫn sức mạnh sấm sét vào cơ thể và luyện hóa thành thần năng. Hắn tiếp tục diễn hóa một chiếc đỉnh ba chân hai tai từ lôi đình, tự nhốt mình bên trong để rèn cả thân thể lẫn nguyên thần. Sau mấy nghìn tia sét, đợt thiên kiếp tưởng như kết thúc lại chuyển thành những lưỡi dao điện mạnh hơn, buộc hắn phải tiếp tục chống đỡ và đưa khí tức lôi đình vào xương sọ. Một quái thú có hình dạng pha trộn giữa sư tử, hổ và trâu bất ngờ xuất hiện, rồi bị nhốt cùng hắn trong đỉnh lôi đình. Trong cuộc giao chiến, quái thú dần thu nhỏ và suy yếu, còn thân thể cùng nguyên thần của Thạch Hạo hấp thu khí tức lôi điện và trở nên mạnh mẽ hơn."},{"chuong":787,"tieuDe":"Đại Kiếp Mạnh Mẽ Nhất","tomTat":"Thạch Hạo luyện hóa hoàn toàn sinh linh trong chiếc đỉnh lôi đình, hấp thu tinh hoa sấm sét để gột rửa thân thể và làm nguyên thần thêm rực rỡ. Rời khỏi đỉnh, hắn tiếp tục chịu thác sét và lôi kiếp băng tuyết đánh đến gần thần hình俱 diệt, nhưng nhờ vận chuyển Bảo thuật Lôi Đế và giải phóng tiềm năng, hắn tìm được sinh cơ, phá băng rồi hấp thu năng lượng còn lại. Sau chín loại thiên kiếp dị thường liên tục khiến thân thể tàn phế rồi tái sinh, tầng kiếp thứ mười bất ngờ giáng xuống, đánh nổ hai tay và chém ngang hông hắn. Thạch Hạo cưỡng ép tụ lại máu thịt, tiến vào dãy núi lôi đình và giao chiến với người cầm phương thiên họa kích cưỡi chiến mã đỏ như máu, một đối thủ có thể hồi sinh mạnh hơn sau mỗi lần bị đánh tan. Hắn phải đồng thời vận dụng Luân Hồi, Côn Bằng và Bảo thuật Lôi Đế để chống đỡ cho đến khi thiên kiếp rút đi. Vượt kiếp thành công, Thạch Hạo đạt Tôn giả Đại viên mãn, thu lấy kiếp quang còn sót để bồi bổ thể xác và nguyên thần. Cuối cùng, hắn phát hiện ao lôi dịch cổ xưa sâu trong tầng mây và lao tới, dự định dùng nguồn lực này chữa lành thương thế rồi hoàn thành lần lột xác tiếp theo."},{"chuong":788,"tieuDe":"Sức Sống Mới Trong Lôi Trì","tomTat":"Sau khi vượt qua thiên kiếp với thương thế gần như tàn phế, Thạch Hạo tiến vào Lôi trì trong tầng mây sấm sét và uống Lôi kiếp dịch màu tím. Sinh mệnh lực trong thần dịch nhanh chóng nối lại xương gãy, phục hồi gân mạch, chữa lành thân thể và gột rửa nguyên thần của hắn. Quá trình không dừng ở chữa thương mà tiếp tục tái tạo xương thịt, khiến thể phách cùng nguyên thần hoàn thành một lần lột xác sâu và mạnh hơn trước rất nhiều. Trong trạng thái ngộ đạo, Thạch Hạo hiểu Nguyên Thủy Chân Giải cùng Vạn Linh đồ tường tận hơn, đồng thời nhìn rõ hơn con đường nhen lửa vạn đạo để tiến vào Thần Hỏa cảnh. Dị tượng sen vàng và cánh hoa quanh hắn cũng hóa thành thủ đoạn sát phạt chân thực có thể phá nát và làm vặn vẹo hư không. Nhìn lên tầng trời cao hơn, hắn phát hiện kiếp Thần linh cùng một ao màu vàng và nhiều cảnh tượng siêu phàm, nhưng hiểu rằng bản thân chưa đủ sức tiến vào. Thạch Hạo thử thu Lôi kiếp dịch bằng đỉnh xương nhưng thần dịch lập tức bốc hơi, khiến hắn nhớ tới lời Tề Đạo Lâm và kết cục của Tam Quan Vương vì cưỡng cầu toàn bộ căn nguyên vận may. Cuối cùng hắn hấp thu gần nửa ao rồi nhanh chóng rút lui, ngay sau đó Lôi trì bị sấm sét nhấn chìm."},{"chuong":789,"tieuDe":"Gặp Lại","tomTat":"Sau khi sống sót qua lôi kiếp, Thạch Hạo nhờ Đả Thần Thạch đưa tới một nơi yên tĩnh và ngủ mê trong lúc lôi kiếp dịch hóa thành sức sống bản nguyên, thúc đẩy toàn thân biến đổi. Khi tỉnh lại, hắn cảm thấy sức mạnh tăng vọt và phát hiện nhiều điểm sáng thần bí trong cơ thể, nhưng chưa xác định được kho tàng nào đã mở ra hay Chí Tôn cốt có thật sự sống lại hay không. Biết Ninh Xuyên từng tới Tội châu vì hiện tượng chữ Tội phá mây, Thạch Hạo không hề sợ hãi và quyết chiến đến cùng nếu hai người gặp nhau trong Tiên cổ. Hắn trở lại Hoàng đô Hỏa quốc dò hỏi rồi lên đường tới thành Ly Hỏa để tìm cha con Hỏa Hoàng. Trong rừng dâu lửa, hắn gặp lại Hỏa Linh Nhi đang sống giản dị bằng việc hái lá nuôi tằm; nàng nhận ra hắn dù dung mạo đã đổi và bật khóc khi biết hắn còn sống. Sói con dẫn Thạch Hạo tới ngôi mộ không bia chôn chiến y của hắn, giúp hắn hiểu Hỏa Linh Nhi đã đau buồn và tưởng nhớ mình trong thời gian xa cách. Sau khi kể cho nàng biết mình chính là Hoang, Thạch Hạo nghe tiếng chuông triệu tập đại quyết chiến thiên tài ba ngàn châu vang lên, liền hứa sẽ trở về và tuyên bố tiêu diệt mọi đối thủ cố ý nhắm vào mình."},{"chuong":790,"tieuDe":"Tình Cảm Chân Thành","tomTat":"Tiếng chuông triệu tập thiên tài vang khắp ba ngàn châu, báo hiệu cuộc tuyển chọn tiến vào Tiên cổ và đại chiến tranh bá sắp bắt đầu. Trước giờ chia xa, sự chờ đợi vô tư của Hỏa Linh Nhi khiến Thạch Hạo nhận ra tình cảm chân thành của mình dành cho nàng, rồi hai người cùng trồng hai cây dâu lửa và hoa trước nhà tranh làm dấu cho lời hẹn. Thạch Hạo tuyên bố sẽ bước lên đỉnh thần đạo, đuổi theo Liễu Thần và sau khi trở về sẽ dẫn Hỏa Linh Nhi đi ngắm cảnh đẹp khắp thế gian, còn nàng chỉ mong hắn bình an sống sót. Hỏa Linh Nhi kể cha con mình từng được Hỏa tộc thượng giới trọng dụng, nhưng Hỏa Hoàng đã nộp thánh dược, trả lại trang viên và đưa nàng đi phiêu bạt để tránh lòng tham của các thế lực. Nàng cũng cho biết Hỏa Hoàng đã ngao du hơn một năm chưa trở về. Sau khi để lại lôi kiếp dịch, Thạch Hạo hứa sẽ trở lại rồi bay khỏi rừng dâu lửa, để lại một cuộc chia tay đẫm nước mắt và chưa biết sẽ kéo dài bao nhiêu năm."},{"chuong":791,"tieuDe":"Mở Màn","tomTat":"Thạch Hạo lên đường dự Cuộc chiến thiên tài và biết riêng Tội châu đã có tám triệu Tôn giả tranh một vạn suất đi tiếp. Vì bỏ lỡ các vòng tuyển chọn ban đầu, hắn tìm đến Côn môn, giáo phái cổ nay chỉ còn một ông lão nghiện rượu và một thiếu niên, rồi dùng pháp khí cấp thần cùng pháp môn Đại Bằng không hoàn chỉnh đổi lấy tín vật dự thi. Thiếu niên tiết lộ sư phụ tự xưng sống lâu đến mức muốn chết cũng không được, còn thân phận thật của ông lão được xác nhận là Sinh linh Bất Diệt. Tại đạo trường cổ, tám triệu thí sinh được thông báo chỉ có một ngày trong khu vực đặc thù của Linh giới để chọn ra một vạn người trước khi tiến vào khu không người rộng lớn. Thạch Hạo nhận ra cách mở Linh giới tương tự Hư Thần giới rồi cùng toàn bộ thí sinh vượt qua những cánh cửa khổng lồ, chính thức bắt đầu cuộc tuyển chọn. Cùng lúc, nhiều thiên tài cổ đại như Quân Đạo, cô gái tóc đỏ trong quan tài Sinh mệnh và cô gái có sừng rồng lần lượt thức tỉnh để hướng tới vận may Tiên cổ. Cuộc chiến thiên tài được báo trước chỉ là màn mở đầu cho một trận đại chiến cấp Giáo chủ làm náo loạn thượng giới, với Thạch Hạo ở vị trí trung tâm."},{"chuong":792,"tieuDe":"Gặp Lại","tomTat":"Sau khi vượt qua lôi kiếp, Thạch Hạo tới một thung lũng vắng bế quan, hấp thu lôi kiếp dịch rồi mê man trong khi cơ thể tự lưu chuyển vô số ký hiệu kỳ dị. Khi tỉnh lại, hắn cảm thấy sức mạnh tăng vọt và phát hiện nhiều điểm sáng thần bí, song chưa biết biến hóa này là Chí Tôn cốt hồi sinh, Chí tôn huyết phát tác hay một kho tàng thân thể mới. Hắn chia lôi kiếp dịch cho Hoàng Điệp, đồng thời quyết định dùng đại quyết chiến thiên tài ba ngàn châu để kiểm chứng chiến lực và xem Ninh Xuyên là đại địch có thể phải đối đầu trong Tiên cổ. Từ manh mối tại Hoàng đô Hỏa quốc, Thạch Hạo tìm tới thành Ly Hỏa và gặp lại Hỏa Linh Nhi đang sống giản dị bên rừng dâu lửa. Sói con nhận ra hắn rồi dẫn tới ngôi mộ áo Hỏa Linh Nhi từng lập sau khi nghe tin hắn chết, giúp Thạch Hạo hiểu nỗi đau nàng đã chịu trong thời gian xa cách. Khi tiếng chuông triệu tập đại quyết chiến vang lên, Thạch Hạo tiết lộ mình chính là Hoang và hậu duệ tội huyết, sau đó trấn an Hỏa Linh Nhi rằng hắn sẽ đánh bại mọi kẻ nhằm vào mình rồi trở về."},{"chuong":793,"tieuDe":"Linh Giới","tomTat":"Thạch Hạo tiến vào Linh giới và nhận ra thế giới tinh thần của thượng giới vừa rộng lớn vừa chân thực, có bản chất tương tự Hư Thần giới. Tám mươi chiến trường liên kết nhanh chóng biến thành nơi hỗn chiến của tám triệu Tôn giả, còn Thạch Hạo lập uy tại vùng đầm lầy bằng cách giết những kẻ chủ động tập kích. Một thanh niên áo tím thuộc đạo phái Yêu Long dùng Giao long châu đánh lén hắn nhưng bị bảo thuật lôi đình áp đảo và giết chết. Sau hơn hai canh giờ, Thạch Hạo vượt khỏi khu vực có mười vạn người, trong khi hơn bảy triệu Tôn giả thất bại và bị đại trận chuyển khỏi đạo tràng Tội châu. Cấp cao đạo phái Yêu Long nghe đệ tử báo tin, nghi hung thủ là mục tiêu họ đang truy tìm rồi tới đàn cổ Chí tôn quan sát. Những người sống sót được quy tắc Linh giới triệu tập tới đàn cổ để vượt cửa ải cuối và tranh đoạt Chí tôn dịch. Tại lối vào, người của động Hỏa Vân và đạo phái Yêu Long công khai chặn hậu duệ Tội huyết, khiến Thạch Hạo nhận ra hành động này có thể nhằm vào mình nhưng vẫn không sợ thân phận bại lộ."},{"chuong":794,"tieuDe":"Cơn Giận Của Tội Huyết","tomTat":"Tu sĩ Hỏa Vân động và Yêu Long đạo môn ép các thiên tài Tội châu phải vượt ải sau cùng, còn thanh niên áo đỏ dùng Hỏa Vân thước phá hủy bảo cụ và đánh trọng thương những người phản kháng. Ẩn trong đám đông, Thạch Hạo vận dụng pháp tướng sen vàng đánh bật bí bảo, cứu người Tội châu và làm kẻ sử dụng Hỏa Vân thước bị thương. Hắn khảo sát cả tám con đường vào đàn cổ Chí tôn, phát hiện nhiều đạo thống cổ cùng thuộc hạ Ninh Xuyên đang dùng gương báu săn người có chữ Tội phá mây. Sau khi cân nhắc sự bảo vệ của đại trận cấm kỵ và chuẩn bị Đả Thần Thạch giữ Phá giới phù làm đường lui, Thạch Hạo quyết định giết trả. Hắn để chữ Tội rực sáng, quét ngang nhóm La Phù chân cốc và giải vây cho những cô gái Tội châu. Cuối chương, Thạch Hạo chuyển sang con đường do Yêu Long đạo môn và Hỏa Vân động trấn giữ, chuẩn bị hoàn toàn bùng phát."},{"chuong":795,"tieuDe":"Ma Vương Ra Oai","tomTat":"Trên một con đường dẫn tới đàn cổ Chí tôn, người của Yêu Long đạo môn và Hỏa Vân động chặn các Tôn giả Tội châu, khiến hai bên chuẩn bị giao chiến. Thạch Hạo bước vào cuộc đối đầu và bị một cường giả trẻ tuổi dùng cốt kính soi ra chữ tội cùng minh văn đại hung trên trán. Nhận ra La Phù chân cốc, Yêu Long đạo môn và Hỏa Vân động đều tham gia nhắm vào người Tội châu, hắn phong tỏa chiến trường và giết kẻ định chạy đi báo tin. Thanh niên áo đỏ dùng Hỏa Vân thước, còn cô gái Yêu Long đạo môn vận dụng Khốn Tiên tác, nhưng cả hai bí bảo đều không ngăn được Thạch Hạo. Trong lúc bản thể áp đảo đối thủ, các linh thân của hắn truy sát toàn bộ những người đi cầu viện. Thạch Hạo giết thanh niên áo đỏ, chém đầu cô gái và đánh gục những kẻ còn lại, khiến người Tội châu phấn chấn còn các Tôn giả cùng Thiên Thần đứng xa kinh hãi. Cuối cùng, hắn đứng trước đàn cổ Chí tôn và tuyên bố cấm môn đồ của cả ba đạo thống tiến lên, đe dọa giết bất kỳ ai tới gần."},{"chuong":796,"tieuDe":"Một Người Cũng Đủ Giữ Ải","tomTat":"Trước khi chính thức leo đàn cổ Chí tôn, Thạch Hạo dùng nguyên thần hóa thành thần kiếm, nhận diện qua tiêu chí phù văn rồi giết sạch các đệ tử Yêu Long đạo môn và Hỏa Vân động đang trà trộn trong đám đông. Hắn phát huy Súc địa thành thốn tới cực hạn, chạy vòng quanh đàn cổ và tiêu diệt người ngăn đường tại năm phương hướng, khiến ba hướng còn lại không dám tiếp tục tiến lên. Sau đó, Thạch Hạo nhanh chóng vượt qua ba tầng đầu bất chấp áp lực ngày càng mạnh và đứng tại nơi tám con đường hợp nhất. Hắn tuyên bố một mình giữ ải, không cho bất kỳ người nào thuộc các đạo thống áp chế Tội châu đi tiếp. Đội ngũ hơn trăm người cùng xông lên vẫn bị hắn giết đến tan tác, thậm chí một cô gái mất hết ý chí phải tự cắt cổ để rời Linh giới. Cuối chương, sáu người áo trắng từ tầng thứ tư quay xuống, mỗi người nâng một hộp báu và tuyên bố sẽ dùng thủ đoạn của Lục Quan Vương để giết Thạch Hạo. Thạch Hạo không hề nao núng mà công khai thách thức Lục Quan Vương cùng những kẻ tới đối phó mình."},{"chuong":797,"tieuDe":"Sát Ý Của Lục Quan Vương","tomTat":"Sáu thuộc hạ áo trắng của Ninh Xuyên từ tầng thứ tư đi xuống, phối hợp với hơn trăm Tôn giả của hai giáo cổ xưa để vây giết Thạch Hạo. Họ lần lượt giải phóng bảo cốt con cháu Chu tước, vảy tím lôi điện, Răng Nghiệt Long, minh châu cùng hai bảo cốt khác, tạo nên thế công gồm sáu loại bảo thuật. Sáu bảo cốt hợp thành một vòng tay tương tự vòng Lục Đạo Chí Tôn, mang sát ý tích tụ từ Ninh Xuyên và đủ sức nhanh chóng tiêu diệt các Tôn giả bị ném vào trong. Thạch Hạo vận dụng sen vàng, lôi thuật và phù văn hộ thể để hóa giải thế công, sau đó dùng tay không kéo tan vòng bảo cốt. Hắn giết cả sáu người áo trắng rồi phái toàn bộ linh thân truy sát sạch nhóm Tôn giả đang tháo chạy. Bất chấp sát khí của các thần linh quan chiến bên ngoài, Thạch Hạo tiếp tục lao lên tế đàn để tranh đoạt Chí tôn dịch trước khi tiến vào khu không người."},{"chuong":798,"tieuDe":"Chí Tôn Dịch","tomTat":"Vòng tay thần bí của phe Lục Quan Vương ghi nhớ khí tức và dao động thần hồn của Thạch Hạo để phục vụ việc truy sát hắn trong Tiên cổ, sau đó được một thiếu nữ gọi trở về. Thạch Hạo tiếp tục leo cổ đàn Chí Tôn, vượt qua áp lực ngày càng mạnh và trở thành người đầu tiên sau tám vạn năm đặt chân lên tầng chín. Khi bia thần hiện ra, hắn khắc chữ “Tội”, tuyên bố đó là vinh quang rồi xác lập kỷ lục tốc độ mới của Tội châu sau hai mươi vạn năm. Tại trung tâm cổ đàn, hắn lấy chén Chí Tôn dịch, uống cạn nhưng chưa luyện hóa mà giữ thần dịch bên ngoài nguyên thần để chuẩn bị cho lúc nhen nhóm Thần hỏa. Vừa rời tế đàn, hắn bị pháp luân giam trong phạm vi mười trượng cùng hàng trăm sát khí chuyên hủy diệt thần hồn. Thạch Hạo phối hợp Cánh Côn Bằng, Luân Hồi quyền và Bảo thuật Lôi đế phá tan pháp luân mà không bị thương. Hắn bắt những Tôn giả định bỏ chạy, lục soát ký ức rồi đánh chết họ. Sau khi biết được những kẻ có liên quan, Thạch Hạo mang sát khí lao thẳng về phía các thần linh đang quan chiến."},{"chuong":799,"tieuDe":"Mạnh Mẽ Tột Cùng","tomTat":"Thạch Hạo tìm tới những thần linh mang dấu hiệu của Hóa Vân động, Yêu Long Đạo môn và La Phù Chân cốc để trả thù vụ tập kích trước đó. Bất chấp lời cảnh cáo về quy tắc tuyển chọn, hắn phá màn sáng bảo thuật, bẻ gãy binh khí, dùng Diệt Hồn châm đánh vào mi tâm thủ lĩnh rồi lấy sấm sét kết liễu nhóm đối thủ đầu tiên. Khi các cổ giáo đòi tước tư cách tiến vào Tiên cổ, Thạch Hạo công khai tố cáo họ từng phá hoại quy tắc và âm thầm dùng pháp khí thần hồn mưu hại mình. Một Thiên Thần ra lệnh tổng công kích, nhưng Thạch Hạo ngưng tụ pháp tướng thần lực thành biển vàng rồi xông thẳng vào đội hình đang bị áp chế xuống Tôn giả cảnh. Hắn dùng sen vàng mang lửa quần sát vòng vây, đồng thời đánh bật bảo tiễn từ mỏ chim thần khiến pháp khí quay lại giết nhiều người cùng phe. Sau hàng chục lượt giao kích, Thạch Hạo đánh mờ bảo luân cấm kỵ, tiếp tục hạ thêm nhiều cường giả và giật lìa một cánh tay của Thiên Thần cầm bảo luân."},{"chuong":800,"tieuDe":"Qua Ải","tomTat":"Thạch Hạo tiếp tục đối đầu lực lượng của nhiều cổ giáo, vượt qua hàng ngũ Tôn giả và sự ngăn cản của ba Thiên Thần để giết Chân Thần từng đe dọa mình. Một Thiên Thần giải thể bức tranh bí khí nhằm áp chế quy tắc Linh giới nhưng bị Thượng Thương Chi Thủ phá hủy, sau đó phải tự chém lìa bả vai để tránh Diệt Hồn châm. Trước khi chiến trường đóng lại, Thạch Hạo dùng Thượng Thương Chi Thủ kết hợp Diệt Hồn châm đánh trúng đầu một Thiên Thần khác, khiến cả ba Thiên Thần vây công đều bị thương nặng. Khi mọi người trở về đạo trường Tội châu, hơn bảy mươi vạn người dự tuyển chỉ còn một vạn Tôn giả thắng cuộc, còn chiến tích của người mang danh Tội làm toàn trường chấn động. Các đạo thống đòi bắt Thạch Hạo và Thiên Thần Hỏa Vân động tìm cách ngăn hắn vào Tiên cổ, nhưng đại trận cổ bảo vệ đạo trường đã chặn sự can thiệp từ bên ngoài. Thạch Hạo tiếp tục giấu thân phận thật, tuyên bố các giáo phái sẽ biết hắn là ai sau khi vào Tiên cổ và hứa thanh toán những sơ đại cùng quái thai cổ đại được phái tới truy sát mình. Cuối chương, tiếng chuông vang lên, đại trận vận chuyển và bắt đầu truyền tống một vạn Tôn giả qua ải tới khu vực rộng lớn không người."}];
